+func TestMaskAPIToken(t *testing.T) {
+	cases := map[string]string{
+		"":                  "",
+		"abc":               "****",
+		"abcd":              "****",
+		"secret-token-1234": "****1234",
+	}
+	for in, want := range cases {
+		if got := maskAPIToken(in); got != want {
+			t.Errorf("maskAPIToken(%q) = %q, want %q", in, got, want)
+		}
+	}
+}
