-		if err != nil {
-			errs.Append(err)
-			return
-		}
-		log.Printf("[INFO] Delete %s\n", f)
-	}
-
-	if c.HasCommandBlock() {
-		links, _ := c.Command.GetLink(c)
-		for _, link := range links {
-			delete(link.From, &errs)
-			delete(link.To, &errs)
