+import com.openmemind.ai.memory.core.data.enums.MemoryCategory;
+import com.openmemind.ai.memory.core.data.enums.MemoryItemType;
+import com.openmemind.ai.memory.core.data.enums.MemoryScope;
+import com.openmemind.ai.memory.core.extraction.rawdata.segment.Segment;
+import java.time.Instant;
+import java.util.List;
+import java.util.Map;
+import org.junit.jupiter.api.DisplayName;
+import org.junit.jupiter.api.Test;
+
+@DisplayName("InMemoryMemoryStore")
+class InMemoryMemoryStoreTest {
+
+    private static final MemoryId MEMORY_ID = DefaultMemoryId.of("user-1", "agent-1");
+    private static final Instant BASE_TIME = Instant.parse("2026-03-21T00:00:00Z");
+
+    @Test
+    @DisplayName("upsertRawData replaces an existing record")
+    void upsertRawDataReplacesExistingRecord() {
+        var store = new InMemoryMemoryStore();
+
+        store.upsertRawData(
+                MEMORY_ID,
+                List.of(rawData("raw-1", "old caption", "content-1", Map.of("source", "seed"))));
+
+        store.upsertRawData(
+                MEMORY_ID,
+                List.of(rawData("raw-1", "new caption", "content-1", Map.of("source", "updated"))));
+
+        assertThat(store.listRawData(MEMORY_ID))
+                .singleElement()
+                .extracting(MemoryRawData::caption)
+                .isEqualTo("new caption");
+    }
+
+    @Test
+    @DisplayName("upsertInsightTypes uses a global namespace")
+    void upsertInsightTypesUsesGlobalNamespace() {
+        var store = new InMemoryMemoryStore();
+
+        store.upsertInsightTypes(List.of(insightType(1L, "profile"), insightType(2L, "agent")));
+
+        assertThat(store.getInsightType("profile")).isPresent();
+        assertThat(store.listInsightTypes())
+                .extracting(MemoryInsightType::name)
+                .containsExactlyInAnyOrder("profile", "agent");
+    }
+
+    @Test
+    @DisplayName("deleteItems removes only requested items")
+    void deleteItemsRemovesOnlyRequestedItems() {
+        var store = new InMemoryMemoryStore();
+
+        store.insertItems(MEMORY_ID, List.of(item(1L), item(2L), item(3L)));
+
+        store.deleteItems(MEMORY_ID, List.of(2L, 3L));
+
+        assertThat(store.listItems(MEMORY_ID)).extracting(MemoryItem::id).containsExactly(1L);
+    }
+
+    @Test
+    @DisplayName("deleteInsights removes only requested insights")
+    void deleteInsightsRemovesOnlyRequestedInsights() {
+        var store = new InMemoryMemoryStore();
+
+        store.upsertInsights(MEMORY_ID, List.of(insight(10L), insight(20L), insight(30L)));
+
+        store.deleteInsights(MEMORY_ID, List.of(20L, 30L));
+
+        assertThat(store.listInsights(MEMORY_ID))
+                .extracting(MemoryInsight::id)
+                .containsExactly(10L);
+    }
+
+    private static MemoryRawData rawData(
+            String id, String caption, String contentId, Map<String, Object> metadata) {
+        return new MemoryRawData(
+                id,
+                MEMORY_ID.toIdentifier(),
+                "conversation",
+                contentId,
+                Segment.single("segment-" + id),
+                caption,
+                null,
+                metadata,
+                BASE_TIME,
+                BASE_TIME,
+                BASE_TIME.plusSeconds(30));
+    }
+
+    private static MemoryInsightType insightType(Long id, String name) {
+        return new MemoryInsightType(
+                id,
+                name,
+                "description-" + name,
+                null,
+                List.of("profile"),
+                600,
+                Map.of("summary", "prompt"),
+                BASE_TIME,
+                BASE_TIME,
+                BASE_TIME,
+                InsightAnalysisMode.BRANCH,
+                null,
+                MemoryScope.USER,
+                List.of("conversation"));
+    }
+
+    private static MemoryItem item(Long id) {
+        return new MemoryItem(
+                id,
+                MEMORY_ID.toIdentifier(),
+                "content-" + id,
+                MemoryScope.USER,
+                MemoryCategory.PROFILE,
+                "conversation",
+                "vector-" + id,
+                "raw-" + id,
+                "hash-" + id,
+                BASE_TIME,
+                Map.of("id", id),
+                BASE_TIME,
+                MemoryItemType.FACT);
+    }
+
+    private static MemoryInsight insight(Long id) {
+        return new MemoryInsight(
+                id,
+                MEMORY_ID.toIdentifier(),
+                "profile",
+                MemoryScope.USER,
+                "name-" + id,
+                List.of("profile"),
+                List.of(
+                        new InsightPoint(
+                                InsightPoint.PointType.SUMMARY, "point-" + id, 0.9f, List.of())),
+                "group",
+                0.9f,
+                BASE_TIME,
+                List.of(),
+                BASE_TIME,
+                BASE_TIME,
+                InsightTier.LEAF,
+                null,
+                List.of(),
+                1);
+    }
+}
