+  'value-with-a-very-long-unbroken-token-that-should-not-force-the-config-page-to-overflow-horizontally-'.repeat(
+    4
+  )
+
+function option(
+  key: string,
+  value: unknown,
+  type: string,
+  constraints: Record<string, unknown> | null = null
+) {
+  return {
+    key,
+    value,
+    description: `${key} description`,
+    type,
+    defaultValue: value,
+    constraints,
+  }
+}
+
+function api(data: unknown, status = 200, code = 'success', message?: string) {
+  return new Response(
+    JSON.stringify({
+      code,
+      data,
+      message,
+      timestamp: '2026-04-30T00:00:00Z',
+    }),
+    {
+      status,
+      headers: { 'content-type': 'application/json' },
+      statusText: message,
+    }
+  )
+}
+
+function renderPage() {
+  const queryClient = new QueryClient({
+    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
+  })
+  return render(
+    <QueryClientProvider client={queryClient}>
+      <SidebarProvider>
+        <SidebarInset>
+          <ConfigPage />
+        </SidebarInset>
+      </SidebarProvider>
+    </QueryClientProvider>
