-const SECRET_LIKE_KEY_PATTERN = new RegExp(
-  [
-    'api[_-]?key',
-    'apiKey',
-    'auth[_-]?token',
-    'authToken',
-    'oauth[_-]?token',
-    'oauthToken',
-    'secret',
-    'password',
-    'passwd',
-    'private[_-]?key',
-    'privateKey',
-  ].join('|'),
-  'i'
-);
-const SECRET_LIKE_VALUE_PATTERNS: readonly { name: string; pattern: RegExp }[] = [
