+            persistentViewEditKeysRef.current.delete(entry.key);
+            setEditRuntimeState(entry.key, {
+              status: result.status,
+              busy: false,
+              error: undefined,
+            });
+          } else if (
+            result.status === "already-resolved" &&
+            result.resolvedAs
+          ) {
+            editHandlesRef.current.delete(entry.key);
+            persistentViewEditKeysRef.current.delete(entry.key);
