+  | "pending"
+  | "view-only"
+  | "accepted"
+  | "rejected"
+  | "skipped"
+  | "ambiguous"
+  | "incomplete"
+  | "unmanaged"
+  | "error"
+  | "historical";
+
+export type DocEditStatus =
+  | "applying"
+  | "pending"
+  | "accepted"
+  | "rejected"
+  | "skipped"
+  | "unmanaged"
