+import { validateSheetTableName } from '../../../util/table-name';
+
+describe('validateSheetTableName', () => {
+    it('accepts a unique custom name', () => {
+        expect(validateSheetTableName('SalesTable', new Set(['OtherTable']))).toEqual({ valid: true });
+    });
+
+    it('rejects duplicate names case-insensitively', () => {
+        expect(validateSheetTableName('SalesTable', new Set(['salestable']))).toEqual({ valid: false, reason: 'invalid' });
+    });
+
+    it('rejects empty names, spaces, and leading numbers', () => {
+        expect(validateSheetTableName('', new Set())).toEqual({ valid: false, reason: 'empty' });
+        expect(validateSheetTableName('Sales Table', new Set())).toEqual({ valid: false, reason: 'invalid' });
+        expect(validateSheetTableName('1SalesTable', new Set())).toEqual({ valid: false, reason: 'invalid' });
+    });
+});
