+      "&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&lt;/a&gt;",
+    );
+  });
+
+  test("leaves a plain string untouched", () => {
+    expect(escapeHtml("just text")).toBe("just text");
+  });
+});
