+
+  test("defaults to the shared PALETTE", () => {
+    expect(colorsForTypes(["A"]).A).toBe(PALETTE[0]);
+  });
+});
+
+describe("hexA", () => {
+  test("expands #RRGGBB plus alpha into rgba()", () => {
