-  if (scope.charAt(0) !== "@") {
-    scope = `@${scope}`;
-  }
-
-  if (spec.scope) {
-    name = `${scope}/${spec.name.split("/")[1]}`;
-  } else {
-    name = `${scope}/${name}`;
-  }
-}
