+// sets the refusal disposition.
+macro_rules! kind_ctors {
+    ($($(#[$doc:meta])* $ctor:ident => $variant:ident),+ $(,)?) => {
+        impl ToolExecutionError {
+            $($(#[$doc])*
+            pub fn $ctor(message: impl Into<String>) -> Self {
+                Self::new(ToolErrorKind::$variant, message)
+            })+
+        }
+    };
+}
