+bool valid_utf8(std::string_view s) {
+  const auto* p = reinterpret_cast<const unsigned char*>(s.data());
+  size_t i = 0;
+  while (i < s.size()) {
+    uint32_t cp = 0;
+    unsigned char c = p[i];
+    size_t extra = 0;
+    if (c <= 0x7f) {
+      ++i;
+      continue;
+    }
+    if (c >= 0xc2 && c <= 0xdf) {
+      cp = c & 0x1fU;
+      extra = 1;
+    }
+    else if (c >= 0xe0 && c <= 0xef) {
+      cp = c & 0x0fU;
+      extra = 2;
+    }
+    else if (c >= 0xf0 && c <= 0xf4) {
+      cp = c & 0x07U;
+      extra = 3;
+    }
+    else {
+      return false;
+    }
+    if (i + extra >= s.size()) {
+      return false;
+    }
+    for (size_t j = 1; j <= extra; ++j) {
+      unsigned char cc = p[i + j];
+      if ((cc & 0xc0U) != 0x80U) {
+        return false;
+      }
+      cp = (cp << 6U) | (cc & 0x3fU);
+    }
+    if ((extra == 2 && cp < 0x800U) || (extra == 3 && cp < 0x10000U) ||
+        (cp >= 0xd800U && cp <= 0xdfffU) || cp > 0x10ffffU) {
+      return false;
+    }
