+	candidates := 0
+	for _, a := range agents {
+		if a.Enabled && a.HasRole {
+			candidates++
+		}
+	}
+	// No candidate for the role at all is not this rule's refusal to make: the
+	// caller's own "no agent has this role" path says something more useful.
+	if candidates == 0 {
+		return result
