+				keptFull++
+			}
+			if AgentMeetsFilter(a, hard, minContext, dropDeprecated) {
+				keptHard++
+			}
+		}
+		if keptFull == 0 && keptHard > 0 {
+			effective = hard
+			result.Relaxed = true
+		}
+	}
+	result.EffectiveCaps = effective
