new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/routefilter_stage_test.go
@@ -0,0 +1,170 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+func routeFilterRequest(agents []RouteAgent, caps uint32, minContext int, drop bool) []byte {
+	out := make([]byte, routeFilterReqHeaderLen+len(agents)*routeFilterAgentLen)
+	binary.LittleEndian.PutUint32(out[0:4], routeFilterRequestMagic)
+	out[4] = wireVersion
+	if drop {
+		out[5] = 1
+	}
+	binary.LittleEndian.PutUint32(out[8:12], uint32(len(agents)))
+	binary.LittleEndian.PutUint32(out[12:16], caps)
+	binary.LittleEndian.PutUint32(out[16:20], uint32(int32(minContext)))
+
+	for i, a := range agents {
+		at := routeFilterReqHeaderLen + i*routeFilterAgentLen
+		var flags uint32
+		if a.Enabled {
+			flags |= routeFilterFlagEnabled
+		}
+		if a.HasRole {
+			flags |= routeFilterFlagHasRole
+		}
+		if a.HaveCap {
+			flags |= routeFilterFlagHaveCap
+		}
+		if a.Deprecated {
+			flags |= routeFilterFlagDeprecated
+		}
+		if a.ToolsEnabled {
+			flags |= routeFilterFlagTools
+		}
+		binary.LittleEndian.PutUint32(out[at:at+4], flags)
+		binary.LittleEndian.PutUint32(out[at+4:at+8], a.CapFlags)
+		binary.LittleEndian.PutUint32(out[at+8:at+12], uint32(int32(a.OverrideContext)))
+		binary.LittleEndian.PutUint32(out[at+12:at+16], uint32(int32(a.CatalogContext)))
+		binary.LittleEndian.PutUint32(out[at+16:at+20], uint32(int32(a.CLIContext)))
+	}
+	return out
+}
+
+func callRouteFilter(t *testing.T, agents []RouteAgent, caps uint32, minContext int,
+	drop bool) RouteFilterResult {
+	t.Helper()
+	response, status := Handle(bus.ModuleInvocation{StageID: StageRouteFilter},
+		routeFilterRequest(agents, caps, minContext, drop))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %v, want OK", status)
+	}
+	if len(response) != 16+len(agents)*4 ||
+		binary.LittleEndian.Uint32(response[0:4]) != routeFilterResponseMagic {
+		t.Fatal("bad response")
+	}
+	out := RouteFilterResult{
+		Kept:          int(binary.LittleEndian.Uint32(response[4:8])),
+		Relaxed:       binary.LittleEndian.Uint32(response[8:12]) == 1,
+		EffectiveCaps: binary.LittleEndian.Uint32(response[12:16]),
+		Keep:          make([]bool, len(agents)),
+	}
+	for i := range agents {
+		out.Keep[i] = binary.LittleEndian.Uint32(response[16+i*4:20+i*4]) == 1
+	}
+	return out
+}
+
+func TestRouteFilterStageCarriesTheDecision(t *testing.T) {
+	vision := capableAgent()
+	textOnly := capableAgent()
+	textOnly.CapFlags = ModelCapTools
+
+	got := callRouteFilter(t, []RouteAgent{textOnly, vision}, ModelCapTools|ModelCapVision, 0, false)
+	if got.Relaxed || got.Kept != 1 || got.Keep[0] || !got.Keep[1] {
+		t.Errorf("%+v, want only the vision agent kept and no relaxation", got)
+	}
+}
+
+// The fleet-wide part has to survive the wire, including the flag saying it
+// happened and the caps that were actually enforced.
+func TestRouteFilterStageReportsRelaxation(t *testing.T) {
+	textOnly := capableAgent()
+	textOnly.CapFlags = ModelCapTools
+
+	got := callRouteFilter(t, []RouteAgent{textOnly}, ModelCapTools|ModelCapVision, 0, false)
+	if !got.Relaxed {
+		t.Error("relaxation did not survive the wire")
+	}
+	if got.EffectiveCaps != ModelCapTools {
+		t.Errorf("effective caps = %d, want the hard set", got.EffectiveCaps)
+	}
+	if got.Kept != 1 || !got.Keep[0] {
+		t.Errorf("%+v, want the text agent kept", got)
+	}
+}
+
+// Every context source has to arrive intact, or an agent is judged on a window
+// it does not have.
+func TestRouteFilterStageCarriesEveryContextSource(t *testing.T) {
+	cliOnly := RouteAgent{Enabled: true, HasRole: true, ToolsEnabled: true, CLIContext: 128000}
+	if got := callRouteFilter(t, []RouteAgent{cliOnly}, 0, 100000, false); got.Kept != 1 {
+		t.Errorf("the CLI-declared window did not reach the rule: %+v", got)
+	}
+	if got := callRouteFilter(t, []RouteAgent{cliOnly}, 0, 200000, false); got.Kept != 0 {
+		t.Errorf("an agent under the minimum was kept: %+v", got)
+	}
+
+	override := RouteAgent{Enabled: true, HasRole: true, ToolsEnabled: true, HaveCap: true,
+		CatalogContext: 8000, OverrideContext: 400000}
+	if got := callRouteFilter(t, []RouteAgent{override}, 0, 200000, false); got.Kept != 1 {
+		t.Errorf("the override window did not win over the catalog: %+v", got)
+	}
+}
+
+func TestRouteFilterStageCarriesDropDeprecated(t *testing.T) {
+	old := capableAgent()
+	old.Deprecated = true
+	if got := callRouteFilter(t, []RouteAgent{old}, 0, 0, true); got.Kept != 0 {
+		t.Errorf("a deprecated model survived: %+v", got)
+	}
+	if got := callRouteFilter(t, []RouteAgent{old}, 0, 0, false); got.Kept != 1 {
+		t.Errorf("a deprecated model was dropped unasked: %+v", got)
+	}
+}
+
+func TestRouteFilterStageRejectsMalformedRequests(t *testing.T) {
+	good := routeFilterRequest([]RouteAgent{capableAgent()}, ModelCapTools, 0, false)
+
+	cases := map[string][]byte{
+		"empty":         {},
+		"short header":  good[:16],
+		"trailing byte": append(append([]byte{}, good...), 0),
+		"truncated":     good[:len(good)-1],
+	}
+	badMagic := append([]byte{}, good...)
+	binary.LittleEndian.PutUint32(badMagic[0:4], 0xDEADBEEF)
+	cases["wrong magic"] = badMagic
+
+	badVersion := append([]byte{}, good...)
+	badVersion[4] = wireVersion + 1
+	cases["wrong version"] = badVersion
+
+	// A count that does not match the body is the dangerous one: it would read
+	// agents that were never sent.
+	lying := append([]byte{}, good...)
+	binary.LittleEndian.PutUint32(lying[8:12], 5)
+	cases["count disagrees with the body"] = lying
+
+	tooMany := append([]byte{}, good...)
+	binary.LittleEndian.PutUint32(tooMany[8:12], routeFilterMaxAgents+1)
+	cases["agent count over the bound"] = tooMany
+
+	for name, request := range cases {
+		if _, status := Handle(bus.ModuleInvocation{StageID: StageRouteFilter}, request); status != bus.ModuleStatusInvalidRequest {
+			t.Errorf("%s: status = %v, want InvalidRequest", name, status)
+		}
+	}
+}
+
+func TestRouteFilterStageHonoursCancellation(t *testing.T) {
+	invocation := bus.ModuleInvocation{StageID: StageRouteFilter, DeadlineNS: 1}
+	request := routeFilterRequest([]RouteAgent{capableAgent()}, ModelCapTools, 0, false)
+	if _, status := Handle(invocation, request); status != bus.ModuleStatusCancelled {
+		t.Errorf("status = %v, want Cancelled", status)
+	}
+}
diff --git a/server-go/modules/delegates/routefilter_test.go b/server-go/modules/delegates/routefilter_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/routefilter_test.go
@@ -0,0 +1,190 @@
+package delegates
+
+import "testing"
+
+func capableAgent() RouteAgent {
+	return RouteAgent{
+		Enabled: true, HasRole: true,
+		CapFlags: ModelCapTools | ModelCapVision, HaveCap: true,
+		ToolsEnabled: true, CatalogContext: 200000,
+	}
+}
+
+// The agent's own tools setting overrides the catalog in BOTH directions: a
+// capable model on an agent with tools off cannot serve a packet needing tools.
+func TestToolsSettingOverridesTheCatalog(t *testing.T) {
+	a := capableAgent()
+	a.ToolsEnabled = false
+	if AgentMeetsFilter(a, ModelCapTools, 0, false) {
+		t.Error("an agent with tools disabled served a packet requiring tools")
+	}
+
+	// ...and the other way: the agent asserts tools the catalog did not list.
+	b := RouteAgent{Enabled: true, HasRole: true, HaveCap: true, ToolsEnabled: true}
+	if !AgentMeetsFilter(b, ModelCapTools, 0, false) {
+		t.Error("an agent with tools enabled was refused a tools packet")
+	}
+}
+
+// Precedence, most specific first. The CLI window exists because a tmux-CLI
+// agent carries no model to resolve one from, and it must not shadow a real one.
+func TestEffectiveContextPrecedence(t *testing.T) {
+	a := RouteAgent{HaveCap: true, OverrideContext: 111, CatalogContext: 222, CLIContext: 333}
+	if got := EffectiveContext(a); got != 111 {
+		t.Errorf("override should win, got %d", got)
+	}
+	a.OverrideContext = 0
+	if got := EffectiveContext(a); got != 222 {
+		t.Errorf("catalog should win over the CLI, got %d", got)
+	}
+	a.CatalogContext = 0
+	if got := EffectiveContext(a); got != 333 {
+		t.Errorf("the CLI window should be the fallback, got %d", got)
+	}
+	a.CLIContext = 0
+	if got := EffectiveContext(a); got != 0 {
+		t.Errorf("no window should resolve to 0, got %d", got)
+	}
+	// An unknown model must not inherit a catalog window.
+	b := RouteAgent{HaveCap: false, CatalogContext: 999, CLIContext: 100}
+	if got := EffectiveContext(b); got != 100 {
+		t.Errorf("an unknown model used the catalog window anyway, got %d", got)
+	}
+}
+
+func TestMinContextIsEnforced(t *testing.T) {
+	a := capableAgent()
+	a.CatalogContext = 8000
+	if AgentMeetsFilter(a, 0, 200000, false) {
+		t.Error("a small window served a packet needing a large one")
+	}
+	if !AgentMeetsFilter(a, 0, 8000, false) {
+		t.Error("a window exactly meeting the requirement was refused")
+	}
+	// No window at all cannot satisfy a requirement.
+	b := RouteAgent{Enabled: true, HasRole: true, HaveCap: true, ToolsEnabled: true}
+	if AgentMeetsFilter(b, 0, 1, false) {
+		t.Error("an agent with no known window served a packet with a minimum")
+	}
+}
+
+func TestDeprecatedIsDroppedOnlyWhenAsked(t *testing.T) {
+	a := capableAgent()
+	a.Deprecated = true
+	if AgentMeetsFilter(a, 0, 0, true) {
+		t.Error("a deprecated model survived drop_deprecated")
+	}
+	if !AgentMeetsFilter(a, 0, 0, false) {
+		t.Error("a deprecated model was dropped without being asked")
+	}
+	// Deprecation is only known when the catalog knew the model.
+	a.HaveCap = false
+	if !AgentMeetsFilter(a, 0, 0, true) {
+		t.Error("an unknown model was treated as deprecated")
+	}
+}
+
+// The reason this takes the whole fleet: modality is INFERRED from prompt text,
+// so requiring it can wipe out a fleet over a filename. If dropping it leaves
+// somebody, it is dropped.
+func TestModalityIsRelaxedRatherThanFailingTheFleet(t *testing.T) {
+	textOnly := RouteAgent{
+		Enabled: true, HasRole: true,
+		CapFlags: ModelCapTools, HaveCap: true, ToolsEnabled: true, CatalogContext: 200000,
+	}
+	got := RouteFilter([]RouteAgent{textOnly}, ModelCapTools|ModelCapVision, 0, false)
+
+	if !got.Relaxed {
+		t.Error("modality was not relaxed, so a text fleet fails on an inferred capability")
+	}
+	if got.EffectiveCaps != ModelCapTools {
+		t.Errorf("effective caps = %d, want the hard set only", got.EffectiveCaps)
+	}
+	if got.Kept != 1 || !got.Keep[0] {
+		t.Errorf("the text agent was dropped: kept=%d", got.Kept)
+	}
+}
+
+// Relaxation only fires when it CHANGES the outcome. With a capable agent
+// present, the modality requirement stands and the incapable one is dropped.
+func TestModalityStandsWhenSomethingSatisfiesIt(t *testing.T) {
+	vision := capableAgent()
+	textOnly := capableAgent()
+	textOnly.CapFlags = ModelCapTools
+
+	got := RouteFilter([]RouteAgent{textOnly, vision}, ModelCapTools|ModelCapVision, 0, false)
+	if got.Relaxed {
+		t.Error("modality was relaxed even though an agent satisfied it")
+	}
+	if got.Keep[0] {
+		t.Error("the text-only agent was kept for a vision packet")
+	}
+	if !got.Keep[1] || got.Kept != 1 {
+		t.Errorf("the vision agent was dropped: %+v", got)
+	}
+}
+
+// The HARD requirements are asserted by the caller, not inferred, so they are
+// never relaxed -- an empty fleet is the correct answer there.
+func TestHardRequirementsAreNeverRelaxed(t *testing.T) {
+	small := capableAgent()
+	small.CatalogContext = 8000
+
+	got := RouteFilter([]RouteAgent{small}, ModelCapTools|ModelCapVision, 200000, false)
+	if got.Kept != 0 {
+		t.Errorf("an agent that fails min_context was kept: %+v", got)
+	}
+	// Relaxing modality would not have helped, so it must not claim it did.
+	if got.Relaxed {
+		t.Error("relaxation was reported when it could not have changed the outcome")
+	}
+}
+
+// Agents that are disabled or lack the role were never candidates, and the
+// filter must not resurrect them.
+func TestNonCandidatesAreNeverKept(t *testing.T) {
+	disabled := capableAgent()
+	disabled.Enabled = false
+	wrongRole := capableAgent()
+	wrongRole.HasRole = false
+	ok := capableAgent()
+
+	got := RouteFilter([]RouteAgent{disabled, wrongRole, ok}, ModelCapTools, 0, false)
+	if got.Keep[0] || got.Keep[1] {
+		t.Errorf("a non-candidate was kept: %+v", got.Keep)
+	}
+	if !got.Keep[2] || got.Kept != 1 {
+		t.Errorf("the candidate was not kept: %+v", got)
+	}
+}
+
+// Nothing to enforce: every candidate stands, and no work is done.
+func TestNoRequirementsKeepsEveryCandidate(t *testing.T) {
+	a, b := capableAgent(), capableAgent()
+	b.CapFlags = 0
+	b.HaveCap = false
+
+	got := RouteFilter([]RouteAgent{a, b}, 0, 0, false)
+	if got.Kept != 2 || !got.Keep[0] || !got.Keep[1] {
+		t.Errorf("a candidate was dropped with nothing to enforce: %+v", got)
+	}
+}
+
+// No candidate for the role is not this rule's refusal to phrase: the caller
+// has a better message for it.
+func TestNoCandidatesIsEmptyRatherThanRelaxed(t *testing.T) {
+	none := capableAgent()
+	none.HasRole = false
+
+	got := RouteFilter([]RouteAgent{none}, ModelCapTools|ModelCapVision, 0, false)
+	if got.Kept != 0 || got.Relaxed {
+		t.Errorf("%+v, want an empty result with no relaxation claimed", got)
+	}
+}
+
+func TestEmptyFleet(t *testing.T) {
+	got := RouteFilter(nil, ModelCapTools, 1000, true)
+	if got.Kept != 0 || len(got.Keep) != 0 {
+		t.Errorf("%+v, want nothing", got)
+	}
+}
