+      return 0;
+   case DELEGATE_ROLE_OP_AUTO_TOOLS:
+      *out = (int)aimee_delegates_get_u32(response + 16);
+      return 0;
+   case DELEGATE_ROLE_OP_FINAL_TURNS:
+      *out = (int)aimee_delegates_get_u32(response + 20);
+      return 0;
+   default:
+      return -1;
+   }
+}
