diff --git a/server-go/modules/delegates/container_test.go b/server-go/modules/delegates/container_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/container_test.go
@@ -0,0 +1,212 @@
+package delegates
+
+import (
+	"context"
+	"errors"
+	"strings"
+	"testing"
+)
+
+// fakeDocker records what was run and answers from a script, so the sequencing
+// and the failure handling can be tested without a daemon.
+type fakeDocker struct {
+	calls []string
+	// probeOut is what `inspect` returns.
+	probeOut string
+	// probeErr makes the probe itself fail.
+	probeErr bool
+	// failOn makes the named subcommand fail ("create", "start", ...).
+	failOn string
+}
+
+func (f *fakeDocker) run(ctx context.Context, name string, args ...string) (string, error) {
+	sub := ""
+	if len(args) > 0 {
+		sub = args[0]
+	}
+	f.calls = append(f.calls, sub)
+	if f.failOn != "" && sub == f.failOn {
+		return "", errors.New("command failed")
+	}
+	if sub == "inspect" {
+		if f.probeErr {
+			return "", errors.New("probe failed")
+		}
+		return f.probeOut, nil
+	}
+	return "", nil
+}
+
+func (f *fakeDocker) ran(sub string) bool {
+	for _, c := range f.calls {
+		if c == sub {
+			return true
+		}
+	}
+	return false
+}
+
+func startReq(t *testing.T) DockerCreateRequest {
+	t.Helper()
+	spec, err := BuildSandboxSpec(writeReq())
+	if err != nil {
+		t.Fatalf("build spec: %v", err)
+	}
+	return DockerCreateRequest{
+		Spec: spec, ContainerName: "aimee-delegate-1", Image: "ubuntu:22.04",
+	}
+}
+
+// The happy path: created, started, proven isolated, handed over.
+func TestContainerStartIsolated(t *testing.T) {
+	fake := &fakeDocker{probeOut: "none=;"}
+	runner := ContainerRunner{Run: fake.run}
+
+	res, err := runner.Start(context.Background(), startReq(t))
+	if err != nil {
+		t.Fatalf("start: %v", err)
+	}
+	if res.Refused || res.Warned {
+		t.Errorf("an isolated container was not handed over: %+v", res)
+	}
+	if !fake.ran("create") || !fake.ran("start") || !fake.ran("inspect") {
+		t.Errorf("expected create, start and inspect: %v", fake.calls)
+	}
+	if fake.ran("rm") {
+		t.Errorf("an isolated container was destroyed: %v", fake.calls)
+	}
+}
+
+// A container that got a network is not a sandbox, and must not be left
+// running -- a leftover container with network access is exactly what the check
+// exists to prevent.
+func TestContainerStartDestroysOnBreach(t *testing.T) {
+	fake := &fakeDocker{probeOut: "bridge=172.17.0.2;"}
+	runner := ContainerRunner{Run: fake.run, RequireIsolation: true}
+
+	res, err := runner.Start(context.Background(), startReq(t))
+	if err != nil {
+		t.Fatalf("start returned an error rather than a refusal: %v", err)
+	}
+	if !res.Refused {
+		t.Fatalf("a container with network egress was handed over: %+v", res)
+	}
+	if !fake.ran("rm") {
+		t.Errorf("the refused container was left running: %v", fake.calls)
+	}
+	if !strings.Contains(res.Reason, "bypass the egress proxy") {
+		t.Errorf("reason does not say what is at stake: %q", res.Reason)
+	}
+}
+
+// "The probe failed" and "the sandbox is open" are indistinguishable, so under
+// the requirement an unprovable container is destroyed too.
+func TestContainerStartDestroysOnUnprovableIsolation(t *testing.T) {
+	fake := &fakeDocker{probeErr: true}
+	runner := ContainerRunner{Run: fake.run, RequireIsolation: true}
+
+	res, err := runner.Start(context.Background(), startReq(t))
+	if err != nil {
+		t.Fatalf("start: %v", err)
+	}
+	if !res.Refused {
+		t.Fatalf("an unprovable container was handed over: %+v", res)
+	}
+	if !fake.ran("rm") {
+		t.Errorf("the refused container was left running: %v", fake.calls)
+	}
+}
+
+// Without the requirement an unprovable container runs, but not silently.
+func TestContainerStartWarnsWhenIsolationNotRequired(t *testing.T) {
+	fake := &fakeDocker{probeErr: true}
+	runner := ContainerRunner{Run: fake.run}
+
+	res, err := runner.Start(context.Background(), startReq(t))
+	if err != nil {
+		t.Fatalf("start: %v", err)
+	}
+	if res.Refused {
+		t.Errorf("refused without the requirement: %+v", res)
+	}
+	if !res.Warned || res.Reason == "" {
+		t.Errorf("an unverified container ran with nothing reported: %+v", res)
+	}
+	if fake.ran("rm") {
+		t.Errorf("destroyed a container it decided to run: %v", fake.calls)
+	}
+}
+
+// A container that was created but could not start still exists, so it is
+// cleaned up rather than left behind.
+func TestContainerStartCleansUpWhenStartFails(t *testing.T) {
+	fake := &fakeDocker{failOn: "start"}
+	runner := ContainerRunner{Run: fake.run}
+
+	if _, err := runner.Start(context.Background(), startReq(t)); err == nil {
+		t.Fatal("a failed start was reported as success")
+	}
+	if !fake.ran("rm") {
+		t.Errorf("the created container was left behind: %v", fake.calls)
+	}
+}
+
+// Nothing was created, so there is nothing to clean up and no probe to run.
+func TestContainerStartCreateFailure(t *testing.T) {
+	fake := &fakeDocker{failOn: "create"}
+	runner := ContainerRunner{Run: fake.run}
+
+	if _, err := runner.Start(context.Background(), startReq(t)); err == nil {
+		t.Fatal("a failed create was reported as success")
+	}
+	if fake.ran("inspect") {
+		t.Errorf("probed a container that was never created: %v", fake.calls)
+	}
+}
+
+// A spec that lost its guarantees must never reach the daemon.
+func TestContainerStartRefusesABrokenSpecBeforeRunningAnything(t *testing.T) {
+	fake := &fakeDocker{}
+	runner := ContainerRunner{Run: fake.run}
+
+	broken := DockerCreateRequest{
+		Spec: SandboxSpec{
+			ReadOnly: true,
+			Mounts:   []SandboxMount{{Source: "/srv/repo", Target: "/srv/repo"}},
+		},
+		ContainerName: "c1", Image: "ubuntu:22.04",
+	}
+	if _, err := runner.Start(context.Background(), broken); err == nil {
+		t.Fatal("a broken spec was accepted")
+	}
+	if len(fake.calls) != 0 {
+		t.Errorf("ran commands for a spec that should have been refused: %v", fake.calls)
+	}
+}
+
+// The delegate's work is already on the host via the bind mount, so stopping
+// discards only the container.
+func TestContainerStop(t *testing.T) {
+	fake := &fakeDocker{}
+	runner := ContainerRunner{Run: fake.run}
+
+	if err := runner.Stop(context.Background(), "aimee-delegate-1"); err != nil {
+		t.Fatalf("stop: %v", err)
+	}
+	if !fake.ran("rm") {
+		t.Errorf("stop did not remove the container: %v", fake.calls)
+	}
+	if err := runner.Stop(context.Background(), "  "); err == nil {
+		t.Error("an empty container name was accepted")
+	}
+}
+
+func TestContainerRunnerRequiresACommandRunner(t *testing.T) {
+	var runner ContainerRunner
+	if _, err := runner.Start(context.Background(), startReq(t)); err == nil {
+		t.Error("started with no command runner")
+	}
+	if err := runner.Stop(context.Background(), "c1"); err == nil {
+		t.Error("stopped with no command runner")
+	}
+}
diff --git a/server-go/modules/delegates/dockerargs_test.go b/server-go/modules/delegates/dockerargs_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/dockerargs_test.go
@@ -0,0 +1,198 @@
+package delegates
+
+import (
+	"strings"
+	"testing"
+)
+
+func argsFor(t *testing.T, req SandboxRequest) []string {
+	t.Helper()
+	spec, err := BuildSandboxSpec(req)
+	if err != nil {
+		t.Fatalf("build spec: %v", err)
+	}
+	args, err := DockerCreateArgs(DockerCreateRequest{
+		Spec:          spec,
+		ContainerName: "aimee-delegate-1",
+		Image:         "ubuntu:22.04",
+		WorkDir:       req.Worktree,
+	})
+	if err != nil {
+		t.Fatalf("build args: %v", err)
+	}
+	return args
+}
+
+func hasFlagValue(args []string, flag, value string) bool {
+	for i := 0; i+1 < len(args); i++ {
+		if args[i] == flag && args[i+1] == value {
+			return true
+		}
+	}
+	return false
+}
+
+// The one flag the whole design rests on. Never conditional, never
+// configurable.
+func TestDockerArgsAlwaysDisablesNetwork(t *testing.T) {
+	for _, req := range []SandboxRequest{writeReq(), readReq()} {
+		args := argsFor(t, req)
+		if !hasFlagValue(args, "--network", "none") {
+			t.Errorf("--network none missing from %v", args)
+		}
+	}
+}
+
+// A read-only role's workspace must carry :ro all the way to the command, or
+// the enforcement was only ever a comment.
+func TestDockerArgsReadOnlyRoleGetsReadOnlyBind(t *testing.T) {
+	args := argsFor(t, readReq())
+	if !hasFlagValue(args, "-v", "/srv/repo:/srv/repo:ro") {
+		t.Errorf("the parent worktree was not bound read-only: %v", args)
+	}
+	// Only the control socket may be writable.
+	for i := 0; i+1 < len(args); i++ {
+		if args[i] != "-v" {
+			continue
+		}
+		bind := args[i+1]
+		if strings.HasSuffix(bind, ":ro") {
+			continue
+		}
+		if !strings.Contains(bind, "aimee.sock") {
+			t.Errorf("writable bind for a read-only role: %q", bind)
+		}
+	}
+}
+
+// A write role gets the tree readable and only its worktree writable.
+func TestDockerArgsWriteRoleMountModes(t *testing.T) {
+	args := argsFor(t, writeReq())
+	if !hasFlagValue(args, "-v", "/srv/repo:/srv/repo:ro") {
+		t.Errorf("repo not bound read-only: %v", args)
+	}
+	wt := "/srv/repo/.aimee/worktrees/w1/main"
+	if !hasFlagValue(args, "-v", wt+":"+wt) {
+		t.Errorf("worktree not bound writable: %v", args)
+	}
+	gd := "/srv/repo/.git/worktrees/w1"
+	if !hasFlagValue(args, "-v", gd+":"+gd) {
+		t.Errorf("git dir not bound writable: %v", args)
+	}
+}
+
+// The image is the last thing before the command, or docker parses a flag as
+// the image.
+func TestDockerArgsImageAndCommandOrdering(t *testing.T) {
+	spec, err := BuildSandboxSpec(writeReq())
+	if err != nil {
+		t.Fatalf("build spec: %v", err)
+	}
+	args, err := DockerCreateArgs(DockerCreateRequest{
+		Spec: spec, ContainerName: "c1", Image: "ubuntu:22.04",
+		Command: []string{"sleep", "infinity"},
+	})
+	if err != nil {
+		t.Fatalf("build args: %v", err)
+	}
+	for i, a := range args {
+		if a == "ubuntu:22.04" {
+			if i+2 >= len(args) || args[i+1] != "sleep" || args[i+2] != "infinity" {
+				t.Errorf("command does not follow the image: %v", args)
+			}
+			return
+		}
+	}
+	t.Errorf("image missing from %v", args)
+}
+
+// The spec may have travelled by the time it gets here, and a spec that lost
+// its guarantees produces a delegate with a network.
+func TestDockerArgsRevalidatesTheSpec(t *testing.T) {
+	broken := SandboxSpec{
+		ReadOnly: true,
+		Mounts:   []SandboxMount{{Source: "/srv/repo", Target: "/srv/repo"}},
+	}
+	if _, err := DockerCreateArgs(DockerCreateRequest{
+		Spec: broken, ContainerName: "c1", Image: "ubuntu:22.04",
+	}); err == nil {
+		t.Error("a spec with a writable workspace mount for a read-only role was rendered")
+	}
+
+	sock := SandboxSpec{Mounts: []SandboxMount{{
+		Source: "/var/run/docker.sock", Target: "/var/run/docker.sock",
+		Kind: SandboxControlSocket,
+	}}}
+	if _, err := DockerCreateArgs(DockerCreateRequest{
+		Spec: sock, ContainerName: "c1", Image: "ubuntu:22.04",
+	}); err == nil {
+		t.Error("the docker socket was rendered into a create command")
+	}
+}
+
+func TestDockerArgsRejectsHostileImageReference(t *testing.T) {
+	spec, _ := BuildSandboxSpec(writeReq())
+	for _, image := range []string{"", "ubuntu; rm -rf /", "$(id)", "ubuntu\nRUN evil"} {
+		if _, err := DockerCreateArgs(DockerCreateRequest{
+			Spec: spec, ContainerName: "c1", Image: image,
+		}); err == nil {
+			t.Errorf("accepted hostile image %q", image)
+		}
+	}
+}
+
+// Docker resolves bind sources in the DAEMON's namespace. An untranslated path
+// makes a real directory look absent, and docker then creates an empty one --
+// the delegate gets an empty mount and simply appears to find nothing.
+func TestTranslateMountPath(t *testing.T) {
+	table := "/srv/repo\t/host/data/repo\n/run/aimee\t/host/run/aimee\n"
+	cases := []struct{ in, want string }{
+		{"/srv/repo", "/host/data/repo"},
+		{"/srv/repo/sub/file.c", "/host/data/repo/sub/file.c"},
+		{"/run/aimee/server.sock", "/host/run/aimee/server.sock"},
+		// No mapping: unchanged, which is right for a host-native process.
+		{"/elsewhere/path", "/elsewhere/path"},
+	}
+	for _, c := range cases {
+		if got := TranslateMountPath(c.in, table); got != c.want {
+			t.Errorf("%q -> %q, want %q", c.in, got, c.want)
+		}
+	}
+}
+
+// Whole components only: /data must not match /database.
+func TestTranslateMountPathMatchesWholeComponents(t *testing.T) {
+	table := "/data\t/host/data\n"
+	if got := TranslateMountPath("/database/file", table); got != "/database/file" {
+		t.Errorf("/database/file was rewritten by a /data mount: %q", got)
+	}
+	if got := TranslateMountPath("/data/file", table); got != "/host/data/file" {
+		t.Errorf("/data/file -> %q, want /host/data/file", got)
+	}
+}
+
+// The longest destination wins, so a nested mount beats its parent.
+func TestTranslateMountPathLongestMatchWins(t *testing.T) {
+	table := "/srv\t/host/srv\n/srv/repo\t/host/elsewhere/repo\n"
+	if got := TranslateMountPath("/srv/repo/x", table); got != "/host/elsewhere/repo/x" {
+		t.Errorf("nested mount lost to its parent: %q", got)
+	}
+}
+
+// A root mount is the degenerate case and must not double the separator.
+func TestTranslateMountPathRootMount(t *testing.T) {
+	if got := TranslateMountPath("/srv/repo", "/\t/host\n"); got != "/host/srv/repo" {
+		t.Errorf("root mount -> %q, want /host/srv/repo", got)
+	}
+}
+
+// Garbage in the table must not corrupt a path.
+func TestTranslateMountPathIgnoresMalformedRows(t *testing.T) {
+	table := "no-tab-here\n\trelative\tsource\n/srv/repo\t/host/repo\n"
+	if got := TranslateMountPath("/srv/repo/x", table); got != "/host/repo/x" {
+		t.Errorf("malformed rows disturbed the match: %q", got)
+	}
+	if got := TranslateMountPath("relative/path", table); got != "relative/path" {
+		t.Errorf("a relative path was rewritten: %q", got)
+	}
+}
diff --git a/server-go/modules/delegates/economics_stage_test.go b/server-go/modules/delegates/economics_stage_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/economics_stage_test.go
@@ -0,0 +1,107 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+func economicsRequestBytes(tasks []EconomicsTask, agents []AgentTier) []byte {
+	request := make([]byte, economicsReqHeaderLen)
+	binary.LittleEndian.PutUint32(request[0:4], economicsRequestMagic)
+	request[4] = wireVersion
+	binary.LittleEndian.PutUint32(request[8:12], uint32(len(tasks)))
+	binary.LittleEndian.PutUint32(request[12:16], uint32(len(agents)))
+	for _, t := range tasks {
+		var hdr [12]byte
+		binary.LittleEndian.PutUint16(hdr[0:2], uint16(len(t.Status)))
+		binary.LittleEndian.PutUint16(hdr[2:4], uint16(len(t.ClaimedBy)))
+		binary.LittleEndian.PutUint32(hdr[4:8], uint32(len(t.Files)))
+		binary.LittleEndian.PutUint32(hdr[8:12], uint32(len(t.Result)))
+		request = append(request, hdr[:]...)
+		request = append(request, t.Status...)
+		request = append(request, t.ClaimedBy...)
+		request = append(request, t.Files...)
+		request = append(request, t.Result...)
+	}
+	for _, a := range agents {
+		var n [2]byte
+		binary.LittleEndian.PutUint16(n[:], uint16(len(a.Name)))
+		request = append(request, n[:]...)
+		request = append(request, a.Name...)
+		var tier [4]byte
+		binary.LittleEndian.PutUint32(tier[:], uint32(int32(a.Tier)))
+		request = append(request, tier[:]...)
+	}
+	return request
+}
+
+func TestEconomicsStageRoundTrip(t *testing.T) {
+	tasks := []EconomicsTask{
+		{Status: "done", ClaimedBy: "cheap", Files: `["src/a.c"]`,
+			Result: doneHandoff(1, `"src/a.c"`, "")},
+		{Status: "failed", ClaimedBy: "cheap"},
+	}
+	agents := []AgentTier{{Name: "cheap", Tier: 0}}
+
+	response, status := Handle(bus.ModuleInvocation{StageID: StageEconomics},
+		economicsRequestBytes(tasks, agents))
+	if status != bus.ModuleStatusOK || len(response) != economicsResponseLen ||
+		binary.LittleEndian.Uint32(response[0:4]) != economicsResponseMagic {
+		t.Fatalf("status %d, %d bytes", status, len(response))
+	}
+
+	want := BuildEconomicsReport(tasks, agents)
+	if got := int(binary.LittleEndian.Uint32(response[4:8])); got != want.DelegateCount {
+		t.Errorf("delegate count = %d, want %d", got, want.DelegateCount)
+	}
+	at := 4 + 19*4
+	if got := decodeFixed(response[at : at+economicsVerdictLen]); got != want.Verdict {
+		t.Errorf("verdict = %q, want %q", got, want.Verdict)
+	}
+	if got := decodeFixed(response[at+economicsVerdictLen:]); got != want.Recommendation {
+		t.Errorf("recommendation = %q, want %q", got, want.Recommendation)
+	}
+}
+
+func TestEconomicsStageRejectsInvalidEnvelope(t *testing.T) {
+	good := economicsRequestBytes([]EconomicsTask{{Status: "done", ClaimedBy: "a"}}, nil)
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageEconomics},
+		good[:economicsReqHeaderLen-1]); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("truncated status = %d", status)
+	}
+
+	// A task count that outruns the body must be refused, not read past.
+	lying := economicsRequestBytes([]EconomicsTask{{Status: "done"}}, nil)
+	binary.LittleEndian.PutUint32(lying[8:12], 99)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageEconomics}, lying); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("overrunning task count status = %d", status)
+	}
+
+	// Trailing bytes mean the caller and the module disagree about the frame.
+	trailing := append(economicsRequestBytes(nil, nil), 0)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageEconomics}, trailing); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("trailing-byte status = %d", status)
+	}
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageEconomics, DeadlineNS: 1},
+		good); status != bus.ModuleStatusCancelled {
+		t.Errorf("expired status = %d", status)
+	}
+}
+
+// An empty run is answerable, not an error: no delegates ran, so nothing is
+// established either way.
+func TestEconomicsStageEmptyRun(t *testing.T) {
+	response, status := Handle(bus.ModuleInvocation{StageID: StageEconomics},
+		economicsRequestBytes(nil, nil))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %d", status)
+	}
+	at := 4 + 19*4
+	if v := decodeFixed(response[at : at+economicsVerdictLen]); v != "unclear" {
+		t.Errorf("verdict = %q, want unclear", v)
+	}
+}
diff --git a/server-go/modules/delegates/economics_test.go b/server-go/modules/delegates/economics_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/economics_test.go
@@ -0,0 +1,214 @@
+package delegates
+
+import (
+	"strings"
+	"testing"
+)
+
+func doneHandoff(passed int, changed, owned string) string {
+	tests := `[]`
+	if passed > 0 {
+		tests = `[{"name":"t","status":"passed"}]`
+	}
+	return `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":[` + changed + `],"tests":` + tests +
+		`,"supervisor_actions":[],"summary":"did it"}`
+}
+
+// A cheap run whose delegates verified their own work is the shape the cost
+// model is built for.
+func TestEconomicsTier0HeavyIsALikelyWin(t *testing.T) {
+	tasks := []EconomicsTask{
+		{Status: "done", ClaimedBy: "cheap", Files: `["src/a.c"]`,
+			Result: doneHandoff(1, `"src/a.c"`, "")},
+		{Status: "done", ClaimedBy: "cheap", Files: `["src/b.c"]`,
+			Result: doneHandoff(1, `"src/b.c"`, "")},
+	}
+	agents := []AgentTier{{Name: "cheap", Tier: 0}}
+
+	r := BuildEconomicsReport(tasks, agents)
+	if r.DelegateCount != 2 || r.TierCounts[0] != 2 {
+		t.Fatalf("counts = %d delegates, tiers %v", r.DelegateCount, r.TierCounts)
+	}
+	if !r.IsTier0Heavy() {
+		t.Error("two tier-0 delegates should be tier-0 heavy")
+	}
+	if r.ValidHandoffs != 2 || r.InvalidHandoffs != 0 {
+		t.Errorf("handoffs valid=%d invalid=%d", r.ValidHandoffs, r.InvalidHandoffs)
+	}
+	if r.DelegatesWithFocusedTests != 2 || r.FocusedTestsRunByDelegates != 2 {
+		t.Errorf("verification = %d/%d", r.DelegatesWithFocusedTests, r.FocusedTestsRunByDelegates)
+	}
+	if r.Verdict != "likely_net_win" {
+		t.Errorf("verdict = %q", r.Verdict)
+	}
+}
+
+// Expensive seats plus supervisor cleanup is the case the model exists to warn
+// about.
+func TestEconomicsExpensiveWithCleanupIsALikelyLoss(t *testing.T) {
+	tasks := []EconomicsTask{
+		{Status: "failed", ClaimedBy: "dear", Result: `{"agent":"dear"}`},
+		{Status: "done", ClaimedBy: "dear", Files: `["src/a.c"]`, Result: `not a handoff at all`},
+	}
+	agents := []AgentTier{{Name: "dear", Tier: 3}}
+
+	r := BuildEconomicsReport(tasks, agents)
+	if r.TierCounts[3] != 2 || r.UnknownTierCount != 0 {
+		t.Fatalf("tiers = %v unknown=%d", r.TierCounts, r.UnknownTierCount)
+	}
+	if r.InvalidHandoffs != 1 {
+		t.Errorf("invalid handoffs = %d, want 1", r.InvalidHandoffs)
+	}
+	// The failed task and the unbelievable handoff each cost attention.
+	if r.ManualIntegrationEvents != 2 || r.SupervisorActionsRequired != 1 {
+		t.Errorf("manual=%d actions=%d", r.ManualIntegrationEvents, r.SupervisorActionsRequired)
+	}
+	if r.Verdict != "likely_net_loss" {
+		t.Errorf("verdict = %q", r.Verdict)
+	}
+}
+
+// An unknown tier is its own bucket. Counting it as cheap would flatter the run
+// into a win it did not earn.
+func TestEconomicsUnknownTierIsNotCheap(t *testing.T) {
+	tasks := []EconomicsTask{
+		{Status: "done", ClaimedBy: "mystery", Files: `[]`, Result: doneHandoff(1, "", "")},
+	}
+	r := BuildEconomicsReport(tasks, nil)
+	if r.UnknownTierCount != 1 || r.TierCounts[0] != 0 {
+		t.Fatalf("tiers = %v unknown = %d", r.TierCounts, r.UnknownTierCount)
+	}
+	if r.IsTier0Heavy() || r.Verdict == "likely_net_win" {
+		t.Errorf("unknown tier counted as a win: %q", r.Verdict)
+	}
+}
+
+// The tier comes from the result first, then the claimer, then the named agent.
+func TestEconomicsTierPrecedence(t *testing.T) {
+	reported := EconomicsTask{Status: "done", ClaimedBy: "dear", Files: `[]`,
+		Result: `{"agent_cost_tier":0,"schema_version":"delegate_result_v1","status":"done",` +
+			`"changed_files":[],"tests":[{"status":"passed"}],"summary":"x"}`}
+	agents := []AgentTier{{Name: "dear", Tier: 3}}
+	if r := BuildEconomicsReport([]EconomicsTask{reported}, agents); r.TierCounts[0] != 1 {
+		t.Errorf("reported tier ignored: %v", r.TierCounts)
+	}
+
+	named := EconomicsTask{Status: "done", Files: `[]`,
+		Result: `{"agent_name":"dear","schema_version":"delegate_result_v1","status":"done",` +
+			`"changed_files":[],"tests":[{"status":"passed"}],"summary":"x"}`}
+	if r := BuildEconomicsReport([]EconomicsTask{named}, agents); r.TierCounts[3] != 1 {
+		t.Errorf("named agent's tier not used: %v", r.TierCounts)
+	}
+}
+
+// A handoff carried as a `response` field is still the handoff.
+func TestEconomicsFindsHandoffInResponseField(t *testing.T) {
+	inner := doneHandoff(1, `"src/a.c"`, "")
+	asObject := EconomicsTask{Status: "done", ClaimedBy: "cheap", Files: `["src/a.c"]`,
+		Result: `{"response":` + inner + `}`}
+	if r := BuildEconomicsReport([]EconomicsTask{asObject}, nil); r.ValidHandoffs != 1 {
+		t.Errorf("object response: valid=%d invalid=%d", r.ValidHandoffs, r.InvalidHandoffs)
+	}
+}
+
+// Supervisor actions a delegate asked for are attention it spent, and make the
+// run an integration event even when the handoff was believable.
+func TestEconomicsCountsRequestedSupervisorActions(t *testing.T) {
+	result := `{"schema_version":"delegate_result_v1","status":"done","changed_files":[],` +
+		`"tests":[{"status":"passed"}],"supervisor_actions":["review the migration","rerun ci"],` +
+		`"summary":"needs a look"}`
+	r := BuildEconomicsReport([]EconomicsTask{
+		{Status: "done", ClaimedBy: "cheap", Files: `[]`, Result: result},
+	}, []AgentTier{{Name: "cheap", Tier: 0}})
+
+	if r.SupervisorActionsRequired != 2 || r.ManualIntegrationEvents != 1 {
+		t.Errorf("actions=%d manual=%d", r.SupervisorActionsRequired, r.ManualIntegrationEvents)
+	}
+	if r.ValidHandoffs != 1 {
+		t.Errorf("a believable handoff was rejected: %+v", r)
+	}
+}
+
+// Queued work is not a delegate run and must not dilute the counts.
+func TestEconomicsIgnoresUnclaimedPendingTasks(t *testing.T) {
+	r := BuildEconomicsReport([]EconomicsTask{{Status: "pending"}}, nil)
+	if r.DelegateCount != 0 || r.Verdict != "unclear" {
+		t.Errorf("report = %+v", r)
+	}
+}
+
+// Token totals only accumulate from results that reported any.
+func TestEconomicsTokenTotals(t *testing.T) {
+	tasks := []EconomicsTask{
+		{Status: "done", ClaimedBy: "cheap", Files: `[]`,
+			Result: `{"prompt_tokens":100,"completion_tokens":50,"schema_version":"delegate_result_v1",` +
+				`"status":"done","changed_files":[],"tests":[{"status":"passed"}],"summary":"x"}`},
+		{Status: "done", ClaimedBy: "cheap", Files: `[]`, Result: doneHandoff(1, "", "")},
+	}
+	r := BuildEconomicsReport(tasks, []AgentTier{{Name: "cheap", Tier: 0}})
+	if r.PromptTokensTotal != 100 || r.CompletionTokensTotal != 50 ||
+		r.DelegateTokensEstimated != 150 || r.TokenizedDelegateResults != 1 {
+		t.Errorf("tokens = %d/%d/%d over %d results", r.PromptTokensTotal,
+			r.CompletionTokensTotal, r.DelegateTokensEstimated, r.TokenizedDelegateResults)
+	}
+	// 2 delegates * 300, no manual events, no invalid handoffs.
+	if r.SupervisorPromptTokensEstimated != 600 {
+		t.Errorf("supervisor estimate = %d, want 600", r.SupervisorPromptTokensEstimated)
+	}
+}
+
+// Ported from test_delegate_economics.c: cheap seats do NOT buy a win when the
+// supervisor had to step in for most of them. The recommendation still speaks
+// to the tier-0 shape, because that is what the run was -- the verdict and the
+// advice answer different questions.
+func TestEconomicsTier0HeavyWithHighManualIsUnclear(t *testing.T) {
+	withAction := func(file, action string) string {
+		return `{"schema_version":"delegate_result_v1","status":"done","changed_files":["` +
+			file + `"],"tests":[{"name":"unit","status":"passed"}],` +
+			`"supervisor_actions":["` + action + `"],"summary":"done"}`
+	}
+	tasks := []EconomicsTask{
+		{Status: "done", ClaimedBy: "free-a", Files: `["src/a.c"]`,
+			Result: withAction("src/a.c", "resolve API naming")},
+		{Status: "done", ClaimedBy: "free-b", Files: `["src/b.c"]`,
+			Result: withAction("src/b.c", "integrate overlapping changes")},
+	}
+	agents := []AgentTier{{Name: "free-a", Tier: 0}, {Name: "free-b", Tier: 0}}
+
+	r := BuildEconomicsReport(tasks, agents)
+	if !r.IsTier0Heavy() {
+		t.Fatal("two tier-0 delegates should be tier-0 heavy")
+	}
+	if r.ManualIntegrationEvents != 2 {
+		t.Errorf("manual events = %d, want 2", r.ManualIntegrationEvents)
+	}
+	if r.Verdict != "unclear" {
+		t.Errorf("verdict = %q, want unclear", r.Verdict)
+	}
+	if !strings.Contains(r.Recommendation, "broader delegation") {
+		t.Errorf("recommendation = %q", r.Recommendation)
+	}
+}
+
+// A job with no delegates estimates no supervisor cost at all.
+func TestEconomicsZeroDelegateJob(t *testing.T) {
+	r := BuildEconomicsReport(nil, nil)
+	if r.DelegateCount != 0 || r.Verdict != "unclear" ||
+		r.SupervisorPromptTokensEstimated != 0 {
+		t.Errorf("report = %+v", r)
+	}
+}
+
+func TestEconomicsVerdictText(t *testing.T) {
+	for verdict, want := range map[string]string{
+		"likely_net_win":  "likely net supervisor-token win",
+		"likely_net_loss": "likely net supervisor-token loss",
+		"unclear":         "unclear supervisor-token outcome",
+		"nonsense":        "unclear supervisor-token outcome",
+	} {
+		if got := EconomicsVerdictText(verdict); got != want {
+			t.Errorf("%q -> %q, want %q", verdict, got, want)
+		}
+	}
+}
diff --git a/server-go/modules/delegates/handoff_test.go b/server-go/modules/delegates/handoff_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/handoff_test.go
@@ -0,0 +1,216 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"strings"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+const validHandoff = `{"schema_version":"delegate_result_v1","status":"done",` +
+	`"changed_files":["src/foo.c"],"outside_ownership_touches":[],` +
+	`"tests":[{"name":"unit-test-foo","status":"passed"}],` +
+	`"commands_run":["make unit-tests"],"supervisor_actions":[],` +
+	`"summary":"Did the thing."}`
+
+func handoffRequest(text, owned string, requireVerification bool) []byte {
+	request := make([]byte, handoffHeaderLen+len(text)+len(owned))
+	binary.LittleEndian.PutUint32(request[0:4], handoffRequestMagic)
+	request[4] = wireVersion
+	if requireVerification {
+		request[5] = 1
+	}
+	binary.LittleEndian.PutUint32(request[8:12], uint32(len(text)))
+	binary.LittleEndian.PutUint32(request[12:16], uint32(len(owned)))
+	copy(request[handoffHeaderLen:], text)
+	copy(request[handoffHeaderLen+len(text):], owned)
+	return request
+}
+
+func decodeFixed(b []byte) string {
+	if i := strings.IndexByte(string(b), 0); i >= 0 {
+		return string(b[:i])
+	}
+	return string(b)
+}
+
+func handoffCall(t *testing.T, text, owned string, requireVerification bool) HandoffVerdict {
+	t.Helper()
+	response, status := Handle(bus.ModuleInvocation{StageID: StageHandoff},
+		handoffRequest(text, owned, requireVerification))
+	if status != bus.ModuleStatusOK || len(response) != handoffResponseLen ||
+		binary.LittleEndian.Uint32(response[0:4]) != handoffResponseMagic {
+		t.Fatalf("response len %d status %d", len(response), status)
+	}
+	return HandoffVerdict{
+		Valid:                   binary.LittleEndian.Uint32(response[4:8]) == 1,
+		RepairAttempted:         binary.LittleEndian.Uint32(response[8:12]) == 1,
+		DoneWithoutVerification: binary.LittleEndian.Uint32(response[12:16]) == 1,
+		NeedsSupervisorReview:   binary.LittleEndian.Uint32(response[16:20]) == 1,
+		ChangedFilesCount:       int(binary.LittleEndian.Uint32(response[20:24])),
+		OutsideOwnershipCount:   int(binary.LittleEndian.Uint32(response[24:28])),
+		PassedTests:             int(binary.LittleEndian.Uint32(response[28:32])),
+		CommandsRun:             int(binary.LittleEndian.Uint32(response[32:36])),
+		Status:                  decodeFixed(response[36 : 36+handoffStatusLen]),
+		RawStatus:               decodeFixed(response[36+handoffStatusLen : 36+2*handoffStatusLen]),
+		Error:                   decodeFixed(response[36+2*handoffStatusLen:]),
+	}
+}
+
+// Ported from test_delegate_handoff.c.
+func TestValidHandoffParses(t *testing.T) {
+	v := handoffCall(t, validHandoff, `["src/foo.c"]`, true)
+	if !v.Valid || v.Status != "done" || v.RawStatus != "done" {
+		t.Fatalf("verdict = %+v", v)
+	}
+	if v.ChangedFilesCount != 1 || v.CommandsRun != 1 || v.PassedTests != 1 {
+		t.Errorf("counts = %d/%d/%d, want 1/1/1", v.ChangedFilesCount, v.CommandsRun, v.PassedTests)
+	}
+	if v.OutsideOwnershipCount != 0 || v.NeedsSupervisorReview {
+		t.Errorf("clean handoff flagged: %+v", v)
+	}
+}
+
+func TestMalformedHandoffsAreRejectedWithAReason(t *testing.T) {
+	cases := []struct {
+		name, text, wantErr string
+	}{
+		{"empty", "", "empty delegate handoff"},
+		{"not json", "not json at all", "not valid JSON object"},
+		{"wrong schema", `{"schema_version":"v2","status":"done"}`, "delegate_result_v1"},
+		{"unknown status",
+			`{"schema_version":"delegate_result_v1","status":"finished"}`, "invalid handoff status"},
+		{"missing arrays",
+			`{"schema_version":"delegate_result_v1","status":"done","summary":"x"}`,
+			"missing required fields"},
+		// A summary of only whitespace says nothing; same as absent.
+		{"blank summary",
+			`{"schema_version":"delegate_result_v1","status":"done","changed_files":[],` +
+				`"tests":[],"summary":"   "}`, "missing required fields"},
+	}
+	for _, c := range cases {
+		v := handoffCall(t, c.text, "", true)
+		if v.Valid {
+			t.Errorf("%s: accepted", c.name)
+		}
+		if !strings.Contains(v.Error, c.wantErr) {
+			t.Errorf("%s: error = %q, want it to mention %q", c.name, v.Error, c.wantErr)
+		}
+		// Every rejection routes to a human rather than passing silently.
+		if v.Status != statusNeedsReview || !v.NeedsSupervisorReview {
+			t.Errorf("%s: status = %q, want supervisor review", c.name, v.Status)
+		}
+	}
+}
+
+// supervisor_actions is optional, but a non-array is malformed rather than absent.
+func TestSupervisorActionsOptionalButTyped(t *testing.T) {
+	without := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/foo.c"],"tests":[{"status":"passed"}],"summary":"ok"}`
+	if v := handoffCall(t, without, "", true); !v.Valid {
+		t.Errorf("absent supervisor_actions rejected: %q", v.Error)
+	}
+	wrongType := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":[],"tests":[],"supervisor_actions":"nope","summary":"ok"}`
+	if v := handoffCall(t, wrongType, "", true); v.Valid {
+		t.Error("a non-array supervisor_actions was accepted")
+	}
+}
+
+// A delegate does not get to call its own work done with nothing green.
+func TestDoneWithoutVerificationDowngrades(t *testing.T) {
+	unverified := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/foo.c"],"tests":[],"supervisor_actions":[],"summary":"ok"}`
+
+	v := handoffCall(t, unverified, "", true)
+	if !v.Valid || v.Status != "partial" || !v.DoneWithoutVerification {
+		t.Errorf("verdict = %+v, want a partial downgrade", v)
+	}
+
+	v = handoffCall(t, unverified, "", false)
+	if v.Status != "done" || v.DoneWithoutVerification {
+		t.Errorf("verdict = %+v, want done when verification is not required", v)
+	}
+}
+
+// Both spellings are written by delegates; rejecting one would read a verified
+// run as unverified and downgrade it wrongly.
+func TestBothPassSpellingsCount(t *testing.T) {
+	for _, spelling := range []string{"pass", "passed"} {
+		text := `{"schema_version":"delegate_result_v1","status":"done",` +
+			`"changed_files":[],"tests":[{"status":"` + spelling + `"}],"summary":"ok"}`
+		if v := handoffCall(t, text, "", true); v.PassedTests != 1 || v.DoneWithoutVerification {
+			t.Errorf("%q: passed=%d downgraded=%v", spelling, v.PassedTests,
+				v.DoneWithoutVerification)
+		}
+	}
+}
+
+func TestOutsideOwnershipNeedsReview(t *testing.T) {
+	text := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/foo.c","src/bar.c"],"outside_ownership_touches":[],` +
+		`"tests":[{"name":"unit-test-foo","status":"passed"}],"supervisor_actions":[],` +
+		`"summary":"Touched one extra file."}`
+	v := handoffCall(t, text, `["src/foo.c"]`, true)
+	if !v.Valid || v.Status != statusNeedsReview || !v.NeedsSupervisorReview {
+		t.Fatalf("verdict = %+v", v)
+	}
+	if v.OutsideOwnershipCount != 1 || !strings.Contains(v.Error, "outside owned_files") {
+		t.Errorf("count = %d, error = %q", v.OutsideOwnershipCount, v.Error)
+	}
+}
+
+// A file the delegate ADMITTED touching counts once, not twice for also being
+// in changed_files.
+func TestAdmittedTouchCountsOnce(t *testing.T) {
+	text := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/foo.c","src/bar.c"],"outside_ownership_touches":["src/bar.c"],` +
+		`"tests":[{"status":"passed"}],"summary":"ok"}`
+	if v := handoffCall(t, text, `["src/foo.c"]`, true); v.OutsideOwnershipCount != 1 {
+		t.Errorf("count = %d, want 1", v.OutsideOwnershipCount)
+	}
+}
+
+// With no ownership list, ownership was never scoped: inferring violations from
+// an absent list would flag every ordinary run.
+func TestUnscopedOwnershipCountsOnlyAdmittedTouches(t *testing.T) {
+	text := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/a.c","src/b.c"],"outside_ownership_touches":[],` +
+		`"tests":[{"status":"passed"}],"summary":"ok"}`
+	for _, owned := range []string{"", "[]"} {
+		v := handoffCall(t, text, owned, true)
+		if v.OutsideOwnershipCount != 0 || v.NeedsSupervisorReview {
+			t.Errorf("owned=%q: count = %d, review = %v", owned, v.OutsideOwnershipCount,
+				v.NeedsSupervisorReview)
+		}
+	}
+}
+
+// Ownership outranks the verification downgrade: both apply, and the operator
+// needs the more serious one.
+func TestOwnershipOutranksTheVerificationDowngrade(t *testing.T) {
+	text := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/bar.c"],"outside_ownership_touches":[],"tests":[],` +
+		`"summary":"ok"}`
+	v := handoffCall(t, text, `["src/foo.c"]`, true)
+	if v.Status != statusNeedsReview || v.DoneWithoutVerification {
+		t.Errorf("verdict = %+v, want the ownership verdict to win", v)
+	}
+}
+
+func TestHandoffRejectsInvalidEnvelope(t *testing.T) {
+	short := handoffRequest(validHandoff, "", true)[:handoffHeaderLen-1]
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageHandoff}, short); status != bus.ModuleStatusInvalidRequest {
+		t.Fatalf("truncated status = %d", status)
+	}
+	lying := handoffRequest(validHandoff, "", true)
+	binary.LittleEndian.PutUint32(lying[8:12], 9999)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageHandoff}, lying); status != bus.ModuleStatusInvalidRequest {
+		t.Fatalf("length-mismatch status = %d", status)
+	}
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageHandoff, DeadlineNS: 1},
+		handoffRequest(validHandoff, "", true)); status != bus.ModuleStatusCancelled {
+		t.Fatalf("expired status = %d", status)
+	}
+}
diff --git a/server-go/modules/delegates/isolation_test.go b/server-go/modules/delegates/isolation_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/isolation_test.go
@@ -0,0 +1,103 @@
+package delegates
+
+import (
+	"strings"
+	"testing"
+)
+
+// A runtime that did not honour isolation leaves the delegate able to reach the
+// network directly, so the egress allowlist is not in force at all.
+func TestJudgeIsolationBreachAlwaysReported(t *testing.T) {
+	required := JudgeIsolation(IsolationBreached, true)
+	if !required.Refuse {
+		t.Error("a confirmed breach did not refuse when isolation is required")
+	}
+	if !strings.Contains(required.Reason, "bypass the egress proxy") {
+		t.Errorf("reason does not say what is at stake: %q", required.Reason)
+	}
+
+	// Without the requirement it still must not pass silently.
+	optional := JudgeIsolation(IsolationBreached, false)
+	if optional.Refuse {
+		t.Error("refused despite isolation not being required")
+	}
+	if !optional.Warn {
+		t.Error("a confirmed breach was neither refused nor warned about")
+	}
+}
+
+// The point of the setting: "the probe failed" and "the sandbox is open" are
+// indistinguishable from here, so an operator who requires isolation gets a
+// refusal rather than a guess.
+func TestJudgeIsolationUnknownRefusesOnlyWhenRequired(t *testing.T) {
+	required := JudgeIsolation(IsolationUnknown, true)
+	if !required.Refuse {
+		t.Error("an unverifiable container ran while isolation was required")
+	}
+	if !strings.Contains(required.Reason, "cannot be proven isolated") {
+		t.Errorf("reason does not explain the refusal: %q", required.Reason)
+	}
+
+	optional := JudgeIsolation(IsolationUnknown, false)
+	if optional.Refuse {
+		t.Error("an unverifiable container was refused without the requirement")
+	}
+	if !optional.Warn {
+		t.Error("an unverifiable container passed with no warning at all")
+	}
+}
+
+func TestJudgeIsolationConfirmedRuns(t *testing.T) {
+	for _, required := range []bool{true, false} {
+		v := JudgeIsolation(IsolationConfirmed, required)
+		if v.Refuse || v.Warn {
+			t.Errorf("required=%v: a properly isolated container was not allowed: %+v",
+				required, v)
+		}
+	}
+}
+
+// A named network means attachment and an address means reachability; either
+// alone is a breach.
+func TestParseIsolationProbe(t *testing.T) {
+	cases := []struct {
+		name   string
+		report string
+		want   IsolationProbe
+	}{
+		{"no networks at all", "", IsolationConfirmed},
+		{"only the none network", "none=;", IsolationConfirmed},
+		{"none network with whitespace", "  none=  ;\n", IsolationConfirmed},
+		{"named network attached", "bridge=;", IsolationBreached},
+		{"none network but has an address", "none=172.17.0.2;", IsolationBreached},
+		{"named network with an address", "bridge=172.17.0.2;", IsolationBreached},
+		{"one clean one attached", "none=;bridge=172.17.0.3;", IsolationBreached},
+		// Anything that does not match the contract is not evidence of safety.
+		{"unparseable", "something unexpected", IsolationUnknown},
+		{"partial entry", "bridge", IsolationUnknown},
+	}
+	for _, c := range cases {
+		if got := ParseIsolationProbe(c.report, false); got != c.want {
+			t.Errorf("%s: %q -> %v, want %v", c.name, c.report, got, c.want)
+		}
+	}
+}
+
+// A failed probe is never isolated. Reading silence as safety is the mistake
+// this check exists to prevent.
+func TestParseIsolationProbeFailureIsNeverIsolated(t *testing.T) {
+	for _, report := range []string{"", "none=;", "bridge=172.17.0.2;"} {
+		if got := ParseIsolationProbe(report, true); got != IsolationUnknown {
+			t.Errorf("a failed probe reporting %q returned %v, want unknown", report, got)
+		}
+	}
+}
+
+// End to end: an unreachable runtime must not silently produce a running
+// delegate when the operator required isolation.
+func TestIsolationFailedProbeUnderRequirementRefuses(t *testing.T) {
+	probe := ParseIsolationProbe("", true)
+	if v := JudgeIsolation(probe, true); !v.Refuse {
+		t.Errorf("failed probe + required isolation did not refuse: %+v", v)
+	}
+}
diff --git a/server-go/modules/delegates/patchcoord_stage_test.go b/server-go/modules/delegates/patchcoord_stage_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/patchcoord_stage_test.go
@@ -0,0 +1,94 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+func patchRequestBytes(tasks []PatchTask) []byte {
+	request := make([]byte, patchReqHeaderLen)
+	binary.LittleEndian.PutUint32(request[0:4], patchRequestMagic)
+	request[4] = wireVersion
+	binary.LittleEndian.PutUint32(request[8:12], uint32(len(tasks)))
+	for _, t := range tasks {
+		var hdr [20]byte
+		binary.LittleEndian.PutUint32(hdr[0:4], uint32(int32(t.ID)))
+		binary.LittleEndian.PutUint32(hdr[4:8], uint32(int32(t.StepID)))
+		binary.LittleEndian.PutUint16(hdr[8:10], uint16(len(t.Status)))
+		binary.LittleEndian.PutUint16(hdr[10:12], uint16(len(t.Error)))
+		binary.LittleEndian.PutUint32(hdr[12:16], uint32(len(t.Files)))
+		binary.LittleEndian.PutUint32(hdr[16:20], uint32(len(t.Result)))
+		request = append(request, hdr[:]...)
+		request = append(request, t.Status...)
+		request = append(request, t.Error...)
+		request = append(request, t.Files...)
+		request = append(request, t.Result...)
+	}
+	return request
+}
+
+func TestPatchStageRoundTrip(t *testing.T) {
+	tasks := []PatchTask{
+		{ID: 1, StepID: 7, Status: "done", Files: `["src/a.c"]`,
+			Result: packet(`"src/a.c"`, passedTest)},
+		{ID: 2, StepID: 8, Status: "done", Files: `["src/a.c"]`,
+			Result: packet(`"src/a.c"`, passedTest)},
+	}
+	response, status := Handle(bus.ModuleInvocation{StageID: StagePatchCoord},
+		patchRequestBytes(tasks))
+	if status != bus.ModuleStatusOK ||
+		binary.LittleEndian.Uint32(response[0:4]) != patchResponseMagic {
+		t.Fatalf("status %d, %d bytes", status, len(response))
+	}
+	want := BuildPatchReport(tasks)
+
+	count := int(binary.LittleEndian.Uint32(response[4:8]))
+	if count != len(want.Tasks) {
+		t.Fatalf("task count = %d, want %d", count, len(want.Tasks))
+	}
+	if len(response) != patchRespHeaderLen+count*patchTaskRecordLen {
+		t.Fatalf("response length %d does not match %d tasks", len(response), count)
+	}
+	// Reviewable is the field a supervisor acts on, and the overlap must have
+	// stopped exactly one packet.
+	if got := int(binary.LittleEndian.Uint32(response[28:32])); got != want.Reviewable {
+		t.Errorf("reviewable = %d, want %d", got, want.Reviewable)
+	}
+
+	at := patchRespHeaderLen + patchTaskRecordLen // second task record
+	off := 9 * 4
+	second := decodeFixed(response[at+off+patchStateLen : at+off+2*patchStateLen])
+	if second != "needs_supervisor" {
+		t.Errorf("second packet state = %q, want needs_supervisor", second)
+	}
+	if overlap := int(binary.LittleEndian.Uint32(response[at+24 : at+28])); overlap != 1 {
+		t.Errorf("overlap task id = %d, want 1", overlap)
+	}
+}
+
+func TestPatchStageRejectsInvalidEnvelope(t *testing.T) {
+	good := patchRequestBytes([]PatchTask{{ID: 1, Status: "pending"}})
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StagePatchCoord},
+		good[:patchReqHeaderLen-1]); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("truncated status = %d", status)
+	}
+
+	lying := patchRequestBytes([]PatchTask{{ID: 1, Status: "pending"}})
+	binary.LittleEndian.PutUint32(lying[8:12], 99)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StagePatchCoord}, lying); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("overrunning task count status = %d", status)
+	}
+
+	trailing := append(patchRequestBytes(nil), 0)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StagePatchCoord}, trailing); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("trailing-byte status = %d", status)
+	}
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StagePatchCoord, DeadlineNS: 1},
+		good); status != bus.ModuleStatusCancelled {
+		t.Errorf("expired status = %d", status)
+	}
+}
diff --git a/server-go/modules/delegates/patchcoord_test.go b/server-go/modules/delegates/patchcoord_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/patchcoord_test.go
@@ -0,0 +1,215 @@
+package delegates
+
+import "testing"
+
+func packet(files, tests string) string {
+	return `{"schema_version":"delegate_result_v1","status":"done","changed_files":[` + files +
+		`],"tests":` + tests + `,"supervisor_actions":[],"summary":"did it"}`
+}
+
+const passedTest = `[{"name":"unit","status":"passed"}]`
+
+func stateOf(t *testing.T, r PatchReport, taskID int) PatchTaskReport {
+	t.Helper()
+	for _, tr := range r.Tasks {
+		if tr.TaskID == taskID {
+			return tr
+		}
+	}
+	t.Fatalf("task %d missing from report", taskID)
+	return PatchTaskReport{}
+}
+
+// A packet that cleared every check is the only kind a human should look at.
+func TestPatchCleanPacketIsReviewable(t *testing.T) {
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, StepID: 1, Status: "done", Files: `["src/a.c"]`,
+			Result: packet(`"src/a.c"`, passedTest)},
+	})
+	if r.Reviewable != 1 || r.ImplementationPackets != 1 || r.Verified != 1 {
+		t.Fatalf("report = %+v", r)
+	}
+	tr := stateOf(t, r, 1)
+	if tr.PatchState != "reviewable" || !tr.HandoffValid || tr.PassedTests != 1 {
+		t.Errorf("task = %+v", tr)
+	}
+}
+
+// Packets touching different files do not contend, so both are reviewable.
+func TestPatchDisjointPacketsAreBothReviewable(t *testing.T) {
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, Status: "done", Files: `["src/a.c"]`, Result: packet(`"src/a.c"`, passedTest)},
+		{ID: 2, Status: "done", Files: `["src/b.c"]`, Result: packet(`"src/b.c"`, passedTest)},
+	})
+	if r.Reviewable != 2 || r.ImplementationPackets != 2 || r.PatchOverlaps != 0 {
+		t.Fatalf("report = %+v", r)
+	}
+	if r.Verified != 2 || r.FocusedTestsPassed != 2 {
+		t.Errorf("verification = %d verified, %d tests", r.Verified, r.FocusedTestsPassed)
+	}
+}
+
+// Overlap is judged against packets ALREADY reviewable, so one collision stalls
+// the second packet and not the first. Stalling both would make a single shared
+// file block the whole run.
+func TestPatchOverlapStopsOnlyTheSecondPacket(t *testing.T) {
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, Status: "done", Files: `["src/shared.c"]`,
+			Result: packet(`"src/shared.c"`, passedTest)},
+		{ID: 2, Status: "done", Files: `["src/shared.c"]`,
+			Result: packet(`"src/shared.c"`, passedTest)},
+	})
+	if r.Reviewable != 1 || r.PatchOverlaps != 1 || r.NeedsSupervisor != 1 {
+		t.Fatalf("report = %+v", r)
+	}
+	if first := stateOf(t, r, 1); first.PatchState != "reviewable" {
+		t.Errorf("first packet = %q, want reviewable", first.PatchState)
+	}
+	second := stateOf(t, r, 2)
+	if second.PatchState != "needs_supervisor" || second.OverlapTaskID != 1 {
+		t.Errorf("second packet = %+v", second)
+	}
+}
+
+// Packets that never ran, or are still running, are not integration decisions.
+func TestPatchLifecycleStatesBeforeAHandoff(t *testing.T) {
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, Status: "pending"},
+		{ID: 2, Status: "claimed"},
+		{ID: 3, Status: "running"},
+		{ID: 4, Status: "failed", Error: "container died"},
+	})
+	if r.Planned != 1 || r.Running != 2 || r.Failed != 1 {
+		t.Fatalf("report = %+v", r)
+	}
+	if r.ImplementationPackets != 4 {
+		t.Errorf("implementation packets = %d, want 4", r.ImplementationPackets)
+	}
+	if note := stateOf(t, r, 4).Note; note != "container died" {
+		t.Errorf("failure note = %q, want the delegate's own error", note)
+	}
+}
+
+// Each of these is a reason a human must look before anything is integrated.
+func TestPatchReasonsAPacketNeedsASupervisor(t *testing.T) {
+	cases := []struct {
+		name   string
+		task   PatchTask
+		state  string
+		expect func(*testing.T, PatchReport)
+	}{
+		{
+			name: "edits outside ownership",
+			task: PatchTask{ID: 1, Status: "done", Files: `["src/a.c"]`,
+				Result: packet(`"src/a.c","src/other.c"`, passedTest)},
+			state: "needs_supervisor",
+			expect: func(t *testing.T, r PatchReport) {
+				if r.OutsideOwnershipTouches != 1 {
+					t.Errorf("outside ownership = %d, want 1", r.OutsideOwnershipTouches)
+				}
+			},
+		},
+		{
+			name: "base differs from the integration base",
+			task: PatchTask{ID: 1, Status: "done", Files: `["src/a.c"]`,
+				Result: `{"schema_version":"delegate_result_v1","status":"done",` +
+					`"changed_files":["src/a.c"],"tests":` + passedTest +
+					`,"summary":"x","base_commit":"aaa","integration_base_commit":"bbb"}`},
+			state: "needs_supervisor",
+			expect: func(t *testing.T, r PatchReport) {
+				if r.StaleWorktrees != 1 {
+					t.Errorf("stale worktrees = %d, want 1", r.StaleWorktrees)
+				}
+			},
+		},
+		{
+			name: "no handoff at all",
+			task: PatchTask{ID: 1, Status: "done", Files: `["src/a.c"]`,
+				Result: `just prose`},
+			state: "needs_supervisor",
+			expect: func(t *testing.T, r PatchReport) {
+				if r.InvalidHandoffs != 1 {
+					t.Errorf("invalid handoffs = %d, want 1", r.InvalidHandoffs)
+				}
+			},
+		},
+		{
+			name: "delegate reported blocked",
+			task: PatchTask{ID: 1, Status: "done", Files: `["src/a.c"]`,
+				Result: `{"schema_version":"delegate_result_v1","status":"blocked",` +
+					`"changed_files":["src/a.c"],"tests":` + passedTest + `,"summary":"stuck"}`},
+			state:  "needs_supervisor",
+			expect: func(t *testing.T, r PatchReport) {},
+		},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			r := BuildPatchReport([]PatchTask{c.task})
+			if got := stateOf(t, r, 1).PatchState; got != c.state {
+				t.Errorf("state = %q, want %q", got, c.state)
+			}
+			c.expect(t, r)
+		})
+	}
+}
+
+// Work that came back unverified is "returned", not reviewable: nothing is
+// wrong with it, but nobody has shown it works.
+func TestPatchUnverifiedWorkIsReturned(t *testing.T) {
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, Status: "done", Files: `["src/a.c"]`, Result: packet(`"src/a.c"`, `[]`)},
+	})
+	if r.Returned != 1 || r.Reviewable != 0 || r.Verified != 0 {
+		t.Fatalf("report = %+v", r)
+	}
+}
+
+// A reviewer packet is read-only: it is not an implementation packet and does
+// not take an integration state.
+func TestPatchReviewerPacketIsCountedSeparately(t *testing.T) {
+	review := `{"schema_version":"delegate_review_v1","status":"block","findings":[` +
+		`{"severity":"high","owner_packet":"p1"},{"severity":"note"},{"owner_packet":"p2"}]}`
+	r := BuildPatchReport([]PatchTask{{ID: 9, Status: "done", Result: review}})
+
+	if r.ReviewerPackets != 1 || r.ImplementationPackets != 0 {
+		t.Fatalf("report = %+v", r)
+	}
+	if r.ReviewerStatus != "block" {
+		t.Errorf("reviewer status = %q", r.ReviewerStatus)
+	}
+	// "high" blocks, "note" does not, and the unlabelled finding counts as
+	// blocking because unlabelled is not the same as harmless.
+	if r.ReviewerBlockingFindings != 2 {
+		t.Errorf("blocking findings = %d, want 2", r.ReviewerBlockingFindings)
+	}
+	if r.ReviewerOwnerPacketRoutes != 2 {
+		t.Errorf("owner routes = %d, want 2", r.ReviewerOwnerPacketRoutes)
+	}
+	if state := stateOf(t, r, 9).PatchState; state != "reviewer" {
+		t.Errorf("state = %q, want reviewer", state)
+	}
+}
+
+// An unknown base is not evidence of staleness; only two KNOWN, differing
+// commits are.
+func TestPatchStaleBaseNeedsBothCommits(t *testing.T) {
+	onlyBase := `{"schema_version":"delegate_result_v1","status":"done",` +
+		`"changed_files":["src/a.c"],"tests":` + passedTest + `,"summary":"x","base_commit":"aaa"}`
+	r := BuildPatchReport([]PatchTask{
+		{ID: 1, Status: "done", Files: `["src/a.c"]`, Result: onlyBase},
+	})
+	if r.StaleWorktrees != 0 || r.Reviewable != 1 {
+		t.Errorf("an unknown integration base was read as stale: %+v", r)
+	}
+}
+
+// An empty run still answers, and says nothing has been reviewed.
+func TestPatchEmptyRun(t *testing.T) {
+	r := BuildPatchReport(nil)
+	if r.ReviewerStatus != "not_run" || r.RecommendedNextCommand != patchDefaultNext {
+		t.Errorf("report = %+v", r)
+	}
+	if len(r.Tasks) != 0 {
+		t.Errorf("tasks = %+v", r.Tasks)
+	}
+}
diff --git a/server-go/modules/delegates/proxyguard_test.go b/server-go/modules/delegates/proxyguard_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/proxyguard_test.go
@@ -0,0 +1,162 @@
+package delegates
+
+import (
+	"net"
+	"testing"
+)
+
+func TestProxyPortAllowed(t *testing.T) {
+	for _, port := range []int{80, 443} {
+		if !ProxyPortAllowed(port) {
+			t.Errorf("port %d should be allowed", port)
+		}
+	}
+	// Anything else is a different protocol wearing a proxy request.
+	for _, port := range []int{22, 25, 445, 3306, 5432, 6379, 8080, 0, -1, 65535} {
+		if ProxyPortAllowed(port) {
+			t.Errorf("port %d should be refused", port)
+		}
+	}
+}
+
+func TestProxyHostAllowedExactAndWildcard(t *testing.T) {
+	allow := DefaultPackageAllowlist()
+
+	for _, host := range []string{
+		"deb.debian.org", "pypi.org", "files.pythonhosted.org",
+		"DEB.DEBIAN.ORG",     // DNS is case-insensitive
+		"deb.debian.org.",    // a trailing dot is the same name
+		"archive.ubuntu.com", // the wildcard covers the suffix itself
+		"gb.archive.ubuntu.com",
+		"us.archive.ubuntu.com",
+	} {
+		if !ProxyHostAllowed(host, allow) {
+			t.Errorf("%q should be allowed", host)
+		}
+	}
+
+	for _, host := range []string{
+		"", "  ", "evil.com", "pypi.org.evil.com",
+		// The wildcard boundary is a label, not a substring.
+		"notarchive.ubuntu.com",
+		"archive.ubuntu.com.evil.com",
+		"debian.org", // the allowlist names deb.debian.org, not the apex
+	} {
+		if ProxyHostAllowed(host, allow) {
+			t.Errorf("%q should be refused", host)
+		}
+	}
+}
+
+// Every range a package proxy has no business reaching. Each is a way to turn
+// the sandbox's one permitted channel into a request against the host network.
+func TestProxyAddressBlocksNonPublicIPv4(t *testing.T) {
+	blocked := []string{
+		"0.0.0.0", "10.0.0.1", "100.64.0.1", "127.0.0.1",
+		"169.254.169.254", // cloud metadata
+		"172.16.0.1", "172.31.255.255", "192.0.0.1", "192.0.2.1",
+		"192.168.1.1", "198.18.0.1", "198.51.100.1", "203.0.113.1",
+		"224.0.0.1", "240.0.0.1", "255.255.255.255",
+	}
+	for _, s := range blocked {
+		if !ProxyAddressBlocked(net.ParseIP(s)) {
+			t.Errorf("%s should be blocked", s)
+		}
+	}
+
+	for _, s := range []string{"1.1.1.1", "8.8.8.8", "93.184.216.34", "151.101.0.1"} {
+		if ProxyAddressBlocked(net.ParseIP(s)) {
+			t.Errorf("%s should be allowed", s)
+		}
+	}
+}
+
+// Without this a hostile resolver could map a private v4 address into v6 and
+// slip past the v4 checks entirely.
+func TestProxyAddressBlocksIPv4EmbeddedInIPv6(t *testing.T) {
+	cases := []struct {
+		name string
+		addr string
+	}{
+		{"v4-mapped loopback", "::ffff:127.0.0.1"},
+		{"v4-mapped private", "::ffff:10.0.0.1"},
+		{"v4-mapped metadata", "::ffff:169.254.169.254"},
+		{"v4-compatible private", "::192.168.1.1"},
+		{"NAT64 metadata", "64:ff9b::169.254.169.254"},
+		{"NAT64 private", "64:ff9b::10.0.0.1"},
+	}
+	for _, c := range cases {
+		ip := net.ParseIP(c.addr)
+		if ip == nil {
+			t.Fatalf("%s: could not parse %q", c.name, c.addr)
+		}
+		if !ProxyAddressBlocked(ip) {
+			t.Errorf("%s (%s) was not blocked", c.name, c.addr)
+		}
+	}
+
+	// 6to4 carries the v4 address at bytes 2..5: 2002:c0a8:0101:: is
+	// 192.168.1.1.
+	sixToFour := net.ParseIP("2002:c0a8:101::1")
+	if sixToFour == nil {
+		t.Fatal("could not parse the 6to4 address")
+	}
+	if !ProxyAddressBlocked(sixToFour) {
+		t.Error("a 6to4 address embedding a private v4 was not blocked")
+	}
+
+	// A v4-mapped PUBLIC address must still be reachable.
+	if ProxyAddressBlocked(net.ParseIP("::ffff:1.1.1.1")) {
+		t.Error("a v4-mapped public address was blocked")
+	}
+}
+
+func TestProxyAddressBlocksNonPublicIPv6(t *testing.T) {
+	for _, s := range []string{
+		"::",      // unspecified
+		"::1",     // loopback
+		"fc00::1", // unique-local
+		"fd00::1",
+		"fe80::1", // link-local
+		"ff02::1", // multicast
+	} {
+		if !ProxyAddressBlocked(net.ParseIP(s)) {
+			t.Errorf("%s should be blocked", s)
+		}
+	}
+	for _, s := range []string{"2606:4700:4700::1111", "2001:4860:4860::8888"} {
+		if ProxyAddressBlocked(net.ParseIP(s)) {
+			t.Errorf("%s should be allowed", s)
+		}
+	}
+}
+
+// An address that cannot be understood cannot be shown to be public.
+func TestProxyAddressFailsClosed(t *testing.T) {
+	if !ProxyAddressBlocked(nil) {
+		t.Error("a nil address was allowed")
+	}
+	if !ProxyAddressBlocked(net.IP{1, 2, 3}) {
+		t.Error("a malformed address was allowed")
+	}
+}
+
+// The allowlist is specific hosts, not broad wildcards -- one wildcard, for the
+// geographic mirrors.
+func TestDefaultAllowlistIsNarrow(t *testing.T) {
+	wildcards := 0
+	for _, entry := range DefaultPackageAllowlist() {
+		if len(entry) > 0 && entry[0] == '*' {
+			wildcards++
+		}
+	}
+	if wildcards != 1 {
+		t.Errorf("allowlist has %d wildcards, want exactly 1", wildcards)
+	}
+	// A bare wildcard would allow everything.
+	for _, entry := range DefaultPackageAllowlist() {
+		if entry == "*" || entry == "*." {
+			t.Errorf("allowlist contains a catch-all: %q", entry)
+		}
+	}
+}
diff --git a/server-go/modules/delegates/rescue_stage_test.go b/server-go/modules/delegates/rescue_stage_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/rescue_stage_test.go
@@ -0,0 +1,146 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+func rescueRequestBytes(text string, known []string, allowJSON bool, mode byte) []byte {
+	request := make([]byte, rescueReqHeaderLen)
+	binary.LittleEndian.PutUint32(request[0:4], rescueRequestMagic)
+	request[4] = wireVersion
+	if allowJSON {
+		request[5] = 1
+	}
+	request[6] = mode
+	binary.LittleEndian.PutUint32(request[8:12], uint32(len(text)))
+	binary.LittleEndian.PutUint32(request[12:16], uint32(len(known)))
+	request = append(request, text...)
+	for _, name := range known {
+		var n [2]byte
+		binary.LittleEndian.PutUint16(n[:], uint16(len(name)))
+		request = append(request, n[:]...)
+		request = append(request, name...)
+	}
+	return request
+}
+
+func decodeRescueResponse(t *testing.T, response []byte) RescueResult {
+	t.Helper()
+	if len(response) < rescueRespHeaderLen ||
+		binary.LittleEndian.Uint32(response[0:4]) != rescueResponseMagic {
+		t.Fatalf("bad response envelope (%d bytes)", len(response))
+	}
+	out := RescueResult{IsToolCall: binary.LittleEndian.Uint32(response[4:8]) == 1}
+	count := int(binary.LittleEndian.Uint32(response[8:12]))
+	contentLen := int(binary.LittleEndian.Uint32(response[12:16]))
+	at := rescueRespHeaderLen
+	out.Content = string(response[at : at+contentLen])
+	at += contentLen
+	for i := 0; i < count; i++ {
+		idLen := int(binary.LittleEndian.Uint16(response[at : at+2]))
+		nameLen := int(binary.LittleEndian.Uint16(response[at+2 : at+4]))
+		argsLen := int(binary.LittleEndian.Uint32(response[at+4 : at+8]))
+		at += 8
+		call := RescueToolCall{
+			ID:        string(response[at : at+idLen]),
+			Name:      string(response[at+idLen : at+idLen+nameLen]),
+			Arguments: string(response[at+idLen+nameLen : at+idLen+nameLen+argsLen]),
+		}
+		at += idLen + nameLen + argsLen
+		out.Calls = append(out.Calls, call)
+	}
+	if at != len(response) {
+		t.Fatalf("response had %d trailing bytes", len(response)-at)
+	}
+	return out
+}
+
+func TestRescueStageRoundTripsACall(t *testing.T) {
+	text := "Sure.<tool_call><name>bash</name><arguments>{\"command\":\"ls\"}</arguments></tool_call>"
+	response, status := Handle(bus.ModuleInvocation{StageID: StageRescue},
+		rescueRequestBytes(text, []string{"bash"}, true, rescueModeParse))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %d", status)
+	}
+	got := decodeRescueResponse(t, response)
+	if !got.IsToolCall || got.Content != "Sure." || len(got.Calls) != 1 {
+		t.Fatalf("result = %+v", got)
+	}
+	if got.Calls[0].Name != "bash" || got.Calls[0].Arguments != `{"command":"ls"}` {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+}
+
+// The inventory travels in the request, so the same text is a call or not
+// depending on what the caller said it accepts.
+func TestRescueStageUsesTheCallersInventory(t *testing.T) {
+	text := `{"name": "deploy", "arguments": {"env": "prod"}}`
+
+	response, status := Handle(bus.ModuleInvocation{StageID: StageRescue},
+		rescueRequestBytes(text, []string{"bash"}, true, rescueModeParse))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %d", status)
+	}
+	if got := decodeRescueResponse(t, response); len(got.Calls) != 0 {
+		t.Errorf("unknown tool was rescued: %+v", got.Calls)
+	}
+
+	response, status = Handle(bus.ModuleInvocation{StageID: StageRescue},
+		rescueRequestBytes(text, []string{"deploy"}, true, rescueModeParse))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %d", status)
+	}
+	if got := decodeRescueResponse(t, response); len(got.Calls) != 1 {
+		t.Errorf("known tool was not rescued: %+v", got)
+	}
+}
+
+func TestRescueStageDetectModeDoesNotParse(t *testing.T) {
+	text := "<tool_call><name>bash</name><arguments>{}</arguments></tool_call>"
+	response, status := Handle(bus.ModuleInvocation{StageID: StageRescue},
+		rescueRequestBytes(text, []string{"bash"}, true, rescueModeDetect))
+	if status != bus.ModuleStatusOK {
+		t.Fatalf("status = %d", status)
+	}
+	if len(response) != rescueRespHeaderLen {
+		t.Fatalf("detect carried a body of %d bytes", len(response)-rescueRespHeaderLen)
+	}
+	if binary.LittleEndian.Uint32(response[4:8]) != 1 {
+		t.Error("detect missed a tool call")
+	}
+}
+
+func TestRescueStageRejectsInvalidEnvelope(t *testing.T) {
+	good := rescueRequestBytes("hi", []string{"bash"}, true, rescueModeParse)
+
+	short := good[:rescueReqHeaderLen-1]
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRescue}, short); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("truncated status = %d", status)
+	}
+
+	lying := rescueRequestBytes("hi", []string{"bash"}, true, rescueModeParse)
+	binary.LittleEndian.PutUint32(lying[8:12], 9999)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRescue}, lying); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("length-mismatch status = %d", status)
+	}
+
+	// A name length that runs past the buffer must be refused, not read.
+	overrun := rescueRequestBytes("hi", []string{"bash"}, true, rescueModeParse)
+	binary.LittleEndian.PutUint16(overrun[rescueReqHeaderLen+2:rescueReqHeaderLen+4], 9999)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRescue}, overrun); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("overrunning name status = %d", status)
+	}
+
+	badMode := rescueRequestBytes("hi", []string{"bash"}, true, 7)
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRescue}, badMode); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("bad-mode status = %d", status)
+	}
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRescue, DeadlineNS: 1},
+		good); status != bus.ModuleStatusCancelled {
+		t.Errorf("expired status = %d", status)
+	}
+}
diff --git a/server-go/modules/delegates/rescue_test.go b/server-go/modules/delegates/rescue_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/rescue_test.go
@@ -0,0 +1,253 @@
+package delegates
+
+import (
+	"encoding/json"
+	"os"
+	"strings"
+	"testing"
+)
+
+// The golden corpus was generated from the C parser this package replaces, and
+// is now owned here: the generator went with the rule, because regenerating
+// from a C side that no longer implements the dialects would have emptied it.
+// Pinning
+// the Go port against it is what makes this a port rather than a rewrite: every
+// dialect, every refusal and every argument spelling has to agree byte for byte.
+
+type goldenCall struct {
+	ID        string `json:"id"`
+	Name      string `json:"name"`
+	Arguments string `json:"arguments"`
+}
+
+type goldenCase struct {
+	Name         string       `json:"name"`
+	Text         string       `json:"text"`
+	AllowJSON    bool         `json:"allow_json"`
+	RC           int          `json:"rc"`
+	IsToolCall   bool         `json:"is_tool_call"`
+	Content      *string      `json:"content"`
+	Detected     bool         `json:"detected"`
+	DetectedJSON bool         `json:"detected_json"`
+	Calls        []goldenCall `json:"calls"`
+}
+
+type goldenFile struct {
+	KnownTools []string     `json:"known_tools"`
+	Cases      []goldenCase `json:"cases"`
+}
+
+func loadGolden(t *testing.T) goldenFile {
+	t.Helper()
+	raw, err := os.ReadFile("testdata/xml_fallback_golden.json")
+	if err != nil {
+		t.Fatalf("read golden: %v", err)
+	}
+	var g goldenFile
+	if err := json.Unmarshal(raw, &g); err != nil {
+		t.Fatalf("parse golden: %v", err)
+	}
+	if len(g.Cases) == 0 {
+		t.Fatal("golden corpus is empty")
+	}
+	return g
+}
+
+func TestRescueMatchesGoldenCorpus(t *testing.T) {
+	g := loadGolden(t)
+	for _, c := range g.Cases {
+		t.Run(c.Name, func(t *testing.T) {
+			got, rc := RescueParseToolCalls(c.Text, g.KnownTools, c.AllowJSON)
+			if rc != c.RC {
+				t.Errorf("rc = %d, want %d", rc, c.RC)
+			}
+			if got.IsToolCall != c.IsToolCall {
+				t.Errorf("is_tool_call = %v, want %v", got.IsToolCall, c.IsToolCall)
+			}
+			wantContent := ""
+			if c.Content != nil {
+				wantContent = *c.Content
+			}
+			if got.Content != wantContent {
+				t.Errorf("content = %q, want %q", got.Content, wantContent)
+			}
+			if len(got.Calls) != len(c.Calls) {
+				t.Fatalf("call count = %d, want %d (%+v)", len(got.Calls), len(c.Calls), got.Calls)
+			}
+			for i, want := range c.Calls {
+				have := got.Calls[i]
+				if have.ID != want.ID || have.Name != want.Name || have.Arguments != want.Arguments {
+					t.Errorf("call %d = {%s %s %s}, want {%s %s %s}", i,
+						have.ID, have.Name, have.Arguments,
+						want.ID, want.Name, want.Arguments)
+				}
+			}
+		})
+	}
+}
+
+// Ported from test_agent_http.c. Both are shapes the golden corpus does not
+// reach, so they would have been lost with the C tests.
+
+// A nameless <invoke> is not a call, and must not stop a real one that follows
+// it from being found.
+func TestRescueSkipsMalformedInvokeAndKeepsTheValidOne(t *testing.T) {
+	text := "<invoke>\n<parameter name=\"command\">echo ignored</parameter>\n</invoke>\n" +
+		"<invoke name=\"bash\">\n<parameter name=\"command\">echo parsed</parameter>\n</invoke>"
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "bash" || !strings.Contains(got.Calls[0].Arguments, "parsed") {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+}
+
+// A channel payload with an unquoted key is not an object, so it takes the
+// key:value path -- and the brace inside the quoted value must not end the
+// arguments early.
+func TestRescueChannelBalancesBracesInsideAString(t *testing.T) {
+	text := `<|channel>call: bash {command: "echo } ok"}<tool_call|>`
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "bash" || got.Calls[0].Arguments != `{"command":"echo } ok"}` {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+}
+
+// Ported from test_delegate_driver.c.
+
+// "respond" is the synthetic tool a delegate answers through, so it is always
+// dispatchable whether or not it appears in the caller's inventory.
+func TestRescueAlwaysAcceptsRespond(t *testing.T) {
+	text := `{"name":"respond","arguments":{"message":"done"}}`
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "respond" || got.Calls[0].Arguments != `{"message":"done"}` {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+}
+
+// The tool/args spelling, announced in prose: the prose stays as content.
+func TestRescueReadsToolArgsSpellingAfterProse(t *testing.T) {
+	text := `Next I will run {"tool":"bash","args":{"command":"pwd"}}`
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "bash" || got.Calls[0].Arguments != `{"command":"pwd"}` {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+	if !strings.Contains(got.Content, "Next I will run") {
+		t.Errorf("content = %q", got.Content)
+	}
+}
+
+// A block written across lines with indented tags: the name and arguments are
+// trimmed, and the prose before it survives as content.
+func TestRescueReadsAMultilineBlock(t *testing.T) {
+	text := "I will run the command now.\n<tool_call>\n  <name>bash</name>\n" +
+		"  <arguments>{\"command\": \"ls -la\"}</arguments>\n</tool_call>\n"
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "bash" || !strings.Contains(got.Calls[0].Arguments, "ls -la") {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+	if !strings.Contains(got.Content, "run the command") {
+		t.Errorf("content = %q", got.Content)
+	}
+}
+
+// harmony encodes quotes as <|"|>. Decoding them is what makes the payload an
+// object at all, and the decoded quotes must not end the arguments early.
+func TestRescueChannelDecodesQuoteMarkers(t *testing.T) {
+	text := `<|channel>call:bash{command:<|"|>git show 0409c38e<|"|>}<tool_call|>`
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Arguments != `{"command":"git show 0409c38e"}` {
+		t.Errorf("arguments = %q", got.Calls[0].Arguments)
+	}
+}
+
+// A Qwen parameter that looks like a number becomes one, so the executor gets
+// offset 0 rather than the string "0".
+func TestRescueQwenParameterTypesSurvive(t *testing.T) {
+	text := "I need to read the file.\n<tool_call>\n<function=read_file>\n" +
+		"<parameter=path>/tmp/probe.txt</parameter>\n<parameter=offset>0</parameter>\n" +
+		"</function>\n</tool_call>"
+	got, rc := RescueParseToolCalls(text, []string{"read_file"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "read_file" || got.Calls[0].ID != "xml_call_1" {
+		t.Errorf("call = %+v", got.Calls[0])
+	}
+	if got.Calls[0].Arguments != `{"path":"/tmp/probe.txt","offset":0}` {
+		t.Errorf("arguments = %q", got.Calls[0].Arguments)
+	}
+}
+
+// Reasoning is stripped before the bracket dialect is read, so the think block
+// neither hides the call nor leaks into the content.
+func TestRescueMistralAfterAThinkBlock(t *testing.T) {
+	text := "<think>I should inspect the file first.</think>\n" +
+		`[TOOL_CALLS]read_file{"path":"src/main.c","limit":20,"meta":{"nested":true}}`
+	got, rc := RescueParseToolCalls(text, []string{"read_file"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if !strings.Contains(got.Calls[0].Arguments, `"path":"src/main.c"`) ||
+		!strings.Contains(got.Calls[0].Arguments, `"nested":true`) {
+		t.Errorf("arguments = %q", got.Calls[0].Arguments)
+	}
+	if strings.Contains(got.Content, "think") {
+		t.Errorf("reasoning leaked into content: %q", got.Content)
+	}
+}
+
+// The minimax shape: a namespaced block whose body is an <invoke>. Neither the
+// plain nor the namespaced <tool_call> scan finds a name here, so this is what
+// the local-name fallback pass exists for -- and "Bash" folds to the registered
+// spelling on the way out.
+func TestRescueReadsANamespacedInvokeBlock(t *testing.T) {
+	text := "<minimax:tool_call>\n<invoke name=\"Bash\">\n" +
+		"<parameter name=\"description\">Check current branch</parameter>\n" +
+		"<parameter name=\"command\">git branch --show-current</parameter>\n" +
+		"</invoke>\n</minimax:tool_call>"
+	got, rc := RescueParseToolCalls(text, []string{"bash"}, true)
+	if rc != 1 || len(got.Calls) != 1 {
+		t.Fatalf("rc = %d, calls = %+v", rc, got.Calls)
+	}
+	if got.Calls[0].Name != "bash" {
+		t.Errorf("name = %q, want bash", got.Calls[0].Name)
+	}
+	if !strings.Contains(got.Calls[0].Arguments, `"command":"git branch --show-current"`) ||
+		!strings.Contains(got.Calls[0].Arguments, `"description":"Check current branch"`) {
+		t.Errorf("arguments = %q", got.Calls[0].Arguments)
+	}
+}
+
+func TestRescueDetectionMatchesGoldenCorpus(t *testing.T) {
+	g := loadGolden(t)
+	for _, c := range g.Cases {
+		t.Run(c.Name, func(t *testing.T) {
+			// "detected" is the always-allow-JSON detector; "detected_json"
+			// applies the case's own allow_json, which is how the caller asks
+			// whether prose JSON counts.
+			if got := RescueHasToolCalls(c.Text, g.KnownTools, true); got != c.Detected {
+				t.Errorf("detect(allow_json=true) = %v, want %v", got, c.Detected)
+			}
+			if got := RescueHasToolCalls(c.Text, g.KnownTools, c.AllowJSON); got != c.DetectedJSON {
+				t.Errorf("detect(allow_json=%v) = %v, want %v", c.AllowJSON, got, c.DetectedJSON)
+			}
+		})
+	}
+}
diff --git a/server-go/modules/delegates/rolepolicy_test.go b/server-go/modules/delegates/rolepolicy_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/rolepolicy_test.go
@@ -0,0 +1,178 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+// Ported from test_delegate_role.c.
+func TestRoleIsWrite(t *testing.T) {
+	for _, role := range []string{"code", "refactor", "implement", "build"} {
+		if !RoleIsWrite(role) {
+			t.Errorf("%q should be a write role", role)
+		}
+	}
+	for _, role := range []string{"review", "validate", "summarize", "", "unknown"} {
+		if RoleIsWrite(role) {
+			t.Errorf("%q should not be a write role", role)
+		}
+	}
+}
+
+// A write role with tools off cannot fail visibly -- it returns a diff summary
+// of code it never wrote -- so tools-on is the only honest default.
+func TestRoleEnablesToolsByDefault(t *testing.T) {
+	on := []string{"code", "refactor", "review", "search", "execute", "diagnose",
+		"validate", "continuity", "beat-check"}
+	for _, role := range on {
+		if !RoleEnablesToolsByDefault(role) {
+			t.Errorf("%q should enable tools by default", role)
+		}
+	}
+	off := []string{"summarize", "format", "draft", "explain", "reason", "plan", ""}
+	for _, role := range off {
+		if RoleEnablesToolsByDefault(role) {
+			t.Errorf("%q should not enable tools by default", role)
+		}
+	}
+	// Aliases resolve before the policy is applied.
+	for _, alias := range []string{"implement", "reviewer", "inspect", "recall",
+		"verifier", "research", "test", "check", "enforce", "build"} {
+		if !RoleEnablesToolsByDefault(alias) {
+			t.Errorf("alias %q did not resolve to a tools-on role", alias)
+		}
+	}
+}
+
+// Caching is opt-in and only for pure text transforms: the same prompt against
+// a changed working tree must never be answered from cache.
+func TestRoleResultCacheEnabled(t *testing.T) {
+	for _, role := range []string{"summarize", "format", "draft", "synthesize"} {
+		if !RoleResultCacheEnabled(role) {
+			t.Errorf("%q should be cacheable", role)
+		}
+	}
+	for _, role := range []string{"code", "review", "search", "diagnose", "execute", "", "custom"} {
+		if RoleResultCacheEnabled(role) {
+			t.Errorf("%q must not be cacheable", role)
+		}
+	}
+}
+
+func TestRoleAutoToolsForInvocation(t *testing.T) {
+	// An explicit request always wins, even for a one-turn probe.
+	if !RoleAutoToolsForInvocation("summarize", 1, true) {
+		t.Error("explicit tools were ignored")
+	}
+	// One turn is a final-answer smoke probe, so no implicit tools.
+	if RoleAutoToolsForInvocation("code", 1, false) {
+		t.Error("a one-turn run got implicit tools")
+	}
+	if !RoleAutoToolsForInvocation("code", 8, false) {
+		t.Error("a multi-turn write role did not get its default tools")
+	}
+	if RoleAutoToolsForInvocation("summarize", 8, false) {
+		t.Error("a text-transform role got implicit tools")
+	}
+}
+
+func TestRoleFinalAfterTurns(t *testing.T) {
+	for role, want := range map[string]int{
+		"validate": 8, "search": 10, "diagnose": 12,
+		"code": -1, "review": -1, "": -1,
+		// Aliases resolve first.
+		"verifier": 8, "recall": 10, "inspect": 12,
+	} {
+		if got := RoleFinalAfterTurns(role); got != want {
+			t.Errorf("%q = %d, want %d", role, got, want)
+		}
+	}
+}
+
+// continuity and beat-check survived the persona-vs-role cull: they are real
+// read-only inspection actions a novel persona genuinely delegates, not
+// restatements of who the delegate is. They inspect the world bible by default,
+// but a one-turn probe still gets no tools.
+func TestRoleNovelInspectionRoles(t *testing.T) {
+	for _, role := range []string{"continuity", "beat-check"} {
+		if RoleIsWrite(role) {
+			t.Errorf("%q must not be a write role", role)
+		}
+	}
+	if !RoleAutoToolsForInvocation("continuity", -1, false) {
+		t.Error("continuity did not get its default tools")
+	}
+	if !RoleAutoToolsForInvocation("beat-check", 2, false) {
+		t.Error("beat-check did not get its default tools")
+	}
+	if RoleAutoToolsForInvocation("continuity", 1, false) {
+		t.Error("a one-turn continuity probe got implicit tools")
+	}
+}
+
+func rolePolicyRequestBytes(role string, maxTurns int, explicitTools bool) []byte {
+	request := make([]byte, rolePolicyRequestLen)
+	binary.LittleEndian.PutUint32(request[0:4], rolePolicyRequestMagic)
+	request[4] = wireVersion
+	if explicitTools {
+		request[5] = 1
+	}
+	binary.LittleEndian.PutUint32(request[8:12], uint32(int32(maxTurns)))
+	binary.LittleEndian.PutUint32(request[12:16], uint32(len(role)))
+	copy(request[16:], role)
+	return request
+}
+
+func TestRolePolicyStageRoundTrip(t *testing.T) {
+	response, status := Handle(bus.ModuleInvocation{StageID: StageRolePolicy},
+		rolePolicyRequestBytes("implement", 8, false))
+	if status != bus.ModuleStatusOK || len(response) != rolePolicyResponseLen ||
+		binary.LittleEndian.Uint32(response[0:4]) != rolePolicyResponseMagic {
+		t.Fatalf("status %d, %d bytes", status, len(response))
+	}
+	// "implement" is an alias for the write role "code".
+	if binary.LittleEndian.Uint32(response[4:8]) != 1 {
+		t.Error("alias did not resolve to a write role")
+	}
+	if binary.LittleEndian.Uint32(response[8:12]) != 1 {
+		t.Error("write role did not enable tools by default")
+	}
+	if binary.LittleEndian.Uint32(response[12:16]) != 0 {
+		t.Error("a write role was reported cacheable")
+	}
+	if int32(binary.LittleEndian.Uint32(response[20:24])) != -1 {
+		t.Error("code should have no early-final turn")
+	}
+
+	// diagnose has one, and a one-turn probe still gets no implicit tools.
+	response, _ = Handle(bus.ModuleInvocation{StageID: StageRolePolicy},
+		rolePolicyRequestBytes("diagnose", 1, false))
+	if int32(binary.LittleEndian.Uint32(response[20:24])) != 12 {
+		t.Error("diagnose lost its early-final turn")
+	}
+	if binary.LittleEndian.Uint32(response[16:20]) != 0 {
+		t.Error("a one-turn probe got implicit tools")
+	}
+}
+
+func TestRolePolicyStageRejectsInvalidEnvelope(t *testing.T) {
+	good := rolePolicyRequestBytes("code", 4, false)
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRolePolicy},
+		good[:rolePolicyRequestLen-1]); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("truncated status = %d", status)
+	}
+
+	lying := rolePolicyRequestBytes("code", 4, false)
+	binary.LittleEndian.PutUint32(lying[12:16], uint32(roleMax+1))
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRolePolicy}, lying); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("over-long role status = %d", status)
+	}
+
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageRolePolicy, DeadlineNS: 1},
+		good); status != bus.ModuleStatusCancelled {
+		t.Errorf("expired status = %d", status)
+	}
+}
diff --git a/server-go/modules/delegates/sandbox_test.go b/server-go/modules/delegates/sandbox_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/sandbox_test.go
@@ -0,0 +1,225 @@
+package delegates
+
+import (
+	"errors"
+	"strings"
+	"testing"
+)
+
+func writeReq() SandboxRequest {
+	return SandboxRequest{
+		Role:               "code",
+		RepoRoot:           "/srv/repo",
+		Worktree:           "/srv/repo/.aimee/worktrees/w1/main",
+		GitDir:             "/srv/repo/.git/worktrees/w1",
+		IsGitCheckout:      true,
+		ParentSocketHost:   "/run/aimee/server.sock",
+		ParentSocketTarget: "/run/aimee.sock",
+		EgressProxy:        "http://egress:3128",
+	}
+}
+
+func readReq() SandboxRequest {
+	return SandboxRequest{
+		Role:               "review",
+		RepoRoot:           "/srv/repo",
+		Worktree:           "/srv/repo",
+		IsGitCheckout:      true,
+		ParentSocketHost:   "/run/aimee/server.sock",
+		ParentSocketTarget: "/run/aimee.sock",
+	}
+}
+
+func findMount(spec SandboxSpec, target string) (SandboxMount, bool) {
+	for _, m := range spec.Mounts {
+		if m.Target == target {
+			return m, true
+		}
+	}
+	return SandboxMount{}, false
+}
+
+// A write delegate gets the tree readable and only its own worktree writable,
+// so an edit outside its ownership fails at the filesystem rather than being
+// caught later by review.
+func TestSandboxWriteDelegateMountLayering(t *testing.T) {
+	spec, err := BuildSandboxSpec(writeReq())
+	if err != nil {
+		t.Fatalf("build: %v", err)
+	}
+	if spec.ReadOnly {
+		t.Error("a write role produced a read-only sandbox")
+	}
+
+	repo, ok := findMount(spec, "/srv/repo")
+	if !ok || !repo.ReadOnly {
+		t.Errorf("repo mount = %+v, want present and read-only", repo)
+	}
+	worktree, ok := findMount(spec, "/srv/repo/.aimee/worktrees/w1/main")
+	if !ok || worktree.ReadOnly {
+		t.Errorf("worktree mount = %+v, want present and writable", worktree)
+	}
+	// git status refreshes its index here, so a read-only .git breaks it.
+	gitDir, ok := findMount(spec, "/srv/repo/.git/worktrees/w1")
+	if !ok || gitDir.ReadOnly {
+		t.Errorf("git dir mount = %+v, want present and writable", gitDir)
+	}
+}
+
+// The supervisor's live branch. The mount mode is the enforcement -- a delegate
+// that is merely asked not to write can still write.
+func TestSandboxReadOnlyDelegateCannotGetAWritableWorkspace(t *testing.T) {
+	spec, err := BuildSandboxSpec(readReq())
+	if err != nil {
+		t.Fatalf("build: %v", err)
+	}
+	if !spec.ReadOnly {
+		t.Fatal("a read role produced a writable sandbox")
+	}
+	for _, m := range spec.Mounts {
+		if m.Kind == SandboxWorkspace && !m.ReadOnly {
+			t.Errorf("writable workspace mount for a read-only role: %+v", m)
+		}
+	}
+	// Exactly one workspace mount: the parent's worktree, not a fresh one.
+	workspaceMounts := 0
+	for _, m := range spec.Mounts {
+		if m.Kind == SandboxWorkspace {
+			workspaceMounts++
+		}
+	}
+	if workspaceMounts != 1 {
+		t.Errorf("read-only delegate got %d workspace mounts, want 1", workspaceMounts)
+	}
+}
+
+// The socket must stay writable or the delegate cannot connect to its parent at
+// all -- and it is the ONLY thing exempt from the read-only rule.
+func TestSandboxControlSocketStaysWritableForAReadOnlyRole(t *testing.T) {
+	spec, err := BuildSandboxSpec(readReq())
+	if err != nil {
+		t.Fatalf("build: %v", err)
+	}
+	sock, ok := findMount(spec, "/run/aimee.sock")
+	if !ok {
+		t.Fatal("no control socket mount")
+	}
+	if sock.Kind != SandboxControlSocket {
+		t.Errorf("socket mount kind = %v, want control socket", sock.Kind)
+	}
+	if sock.ReadOnly {
+		t.Error("control socket mounted read-only; the delegate could not connect")
+	}
+}
+
+// One flag removes lateral movement and data exfiltration. It is a method, not
+// a field, so no caller can set it to anything else.
+func TestSandboxHasNoNetwork(t *testing.T) {
+	for _, req := range []SandboxRequest{writeReq(), readReq()} {
+		spec, err := BuildSandboxSpec(req)
+		if err != nil {
+			t.Fatalf("build: %v", err)
+		}
+		if spec.NetworkMode() != "none" {
+			t.Errorf("network mode = %q, want none", spec.NetworkMode())
+		}
+	}
+}
+
+// Binding a container runtime socket hands the delegate root-equivalent control
+// of the host daemon. Refused by base name, so it is caught at any path.
+func TestSandboxRefusesContainerRuntimeSockets(t *testing.T) {
+	for _, p := range []string{
+		"/var/run/docker.sock",
+		"/some/other/place/docker.sock",
+		"/run/containerd/containerd.sock",
+		"/run/podman/podman.sock",
+	} {
+		req := writeReq()
+		req.ParentSocketHost = p
+		if _, err := BuildSandboxSpec(req); err == nil {
+			t.Errorf("%s was accepted as a mount source", p)
+		}
+	}
+}
+
+// Without this, any host directory could be mounted into a delegate.
+func TestSandboxRequiresAGitCheckout(t *testing.T) {
+	req := writeReq()
+	req.IsGitCheckout = false
+	_, err := BuildSandboxSpec(req)
+	if !errors.Is(err, ErrNotGitCheckout) {
+		t.Errorf("err = %v, want ErrNotGitCheckout", err)
+	}
+}
+
+// The container performs no authenticated work, so a credential in its
+// environment is a leak with no upside.
+func TestSandboxRefusesCredentialsInTheEnvironment(t *testing.T) {
+	for _, name := range []string{
+		"ANTHROPIC_API_KEY", "GITHUB_TOKEN", "AWS_SECRET_ACCESS_KEY",
+		"DB_PASSWORD", "VAULT_CREDENTIAL", "SESSION_ID", "AUTH_HEADER",
+	} {
+		spec := SandboxSpec{Env: []SandboxEnv{{Name: name, Value: "x"}}}
+		if err := ValidateSandboxSpec(spec); err == nil {
+			t.Errorf("%s was allowed into the sandbox", name)
+		}
+	}
+	// The proxy variables are not credentials and must survive.
+	spec, err := BuildSandboxSpec(writeReq())
+	if err != nil {
+		t.Fatalf("build: %v", err)
+	}
+	var sawProxy bool
+	for _, e := range spec.Env {
+		if e.Name == "http_proxy" && e.Value == "http://egress:3128" {
+			sawProxy = true
+		}
+		if looksLikeCredential(e.Name) {
+			t.Errorf("credential-looking env survived: %s", e.Name)
+		}
+	}
+	if !sawProxy {
+		t.Error("http_proxy missing; a no-network delegate could not install software")
+	}
+}
+
+// Relative paths would resolve against whatever the daemon's cwd happens to be.
+func TestSandboxRequiresAbsolutePaths(t *testing.T) {
+	req := writeReq()
+	req.Worktree = "relative/worktree"
+	if _, err := BuildSandboxSpec(req); err == nil {
+		t.Error("a relative worktree was accepted")
+	}
+
+	req = writeReq()
+	req.RepoRoot = "repo"
+	if _, err := BuildSandboxSpec(req); err == nil {
+		t.Error("a relative repo root was accepted")
+	}
+}
+
+// ValidateSandboxSpec is the backstop: it must reject a hand-built spec that
+// violates an invariant, so the guarantees do not depend on BuildSandboxSpec
+// staying correct.
+func TestValidateRejectsHandBuiltViolations(t *testing.T) {
+	writableWorkspaceForReadRole := SandboxSpec{
+		ReadOnly: true,
+		Mounts:   []SandboxMount{{Source: "/srv/repo", Target: "/srv/repo"}},
+	}
+	if err := ValidateSandboxSpec(writableWorkspaceForReadRole); err == nil {
+		t.Error("a writable workspace mount for a read-only role was accepted")
+	}
+
+	dockerSock := SandboxSpec{
+		Mounts: []SandboxMount{{
+			Source: "/var/run/docker.sock", Target: "/var/run/docker.sock",
+			Kind: SandboxControlSocket,
+		}},
+	}
+	if err := ValidateSandboxSpec(dockerSock); err == nil {
+		t.Error("the docker socket was accepted")
+	} else if !strings.Contains(err.Error(), "runtime socket") {
+		t.Errorf("unexpected error: %v", err)
+	}
+}
diff --git a/server-go/modules/delegates/sandboximage_test.go b/server-go/modules/delegates/sandboximage_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/sandboximage_test.go
@@ -0,0 +1,149 @@
+package delegates
+
+import (
+	"strings"
+	"testing"
+)
+
+// The injection boundary. A package name goes into a shell command inside
+// `docker build`, and that build runs WITH network access -- so anything that
+// escapes the name is arbitrary code execution during image construction.
+func TestSandboxDockerfileRefusesShellInPackageNames(t *testing.T) {
+	hostile := []string{
+		"curl; rm -rf /",
+		"curl && wget evil",
+		"$(id)",
+		"`id`",
+		"pkg|tee",
+		"pkg>out",
+		"pkg out",          // a space is two arguments
+		"pkg\nRUN evil",    // a newline is a new Dockerfile instruction
+		"-flag",            // must start alphanumeric
+		"",                 // empty
+		"pkg'quote",
+		"pkg\"quote",
+		"pkg\\escape",
+	}
+	for _, pkg := range hostile {
+		if _, err := SandboxDockerfile("ubuntu:22.04", []string{pkg}); err == nil {
+			t.Errorf("accepted hostile package name %q", pkg)
+		}
+	}
+}
+
+// Real package names must still work, including the punctuation Debian uses.
+func TestSandboxDockerfileAcceptsRealPackageNames(t *testing.T) {
+	packages := []string{"gcc", "make", "g++", "libssl-dev", "python3.11", "gcc:amd64", "ca_certs"}
+	df, err := SandboxDockerfile("ubuntu:22.04", packages)
+	if err != nil {
+		t.Fatalf("rejected real package names: %v", err)
+	}
+	for _, pkg := range packages {
+		if !strings.Contains(df, pkg) {
+			t.Errorf("%q missing from the dockerfile", pkg)
+		}
+	}
+	if !strings.HasPrefix(df, "FROM ubuntu:22.04\n") {
+		t.Errorf("dockerfile does not start with the base: %q", df)
+	}
+	// The package index must not be left in the image.
+	if !strings.Contains(df, "rm -rf /var/lib/apt/lists/*") {
+		t.Error("apt lists are not cleaned up in the same layer")
+	}
+}
+
+// A base reference is the same injection boundary, and legitimately contains
+// registry and repository separators.
+func TestSandboxDockerfileBaseValidation(t *testing.T) {
+	for _, base := range []string{
+		"ubuntu:22.04",
+		"ghcr.io/org/image:tag",
+		"registry.example.com:5000/team/img:1.2.3",
+	} {
+		if _, err := SandboxDockerfile(base, nil); err != nil {
+			t.Errorf("rejected valid base %q: %v", base, err)
+		}
+	}
+	for _, base := range []string{
+		"", "ubuntu:22.04 && evil", "$(id)", "ubuntu\nRUN evil", "ubuntu;rm",
+	} {
+		if _, err := SandboxDockerfile(base, nil); err == nil {
+			t.Errorf("accepted hostile base %q", base)
+		}
+	}
+}
+
+// A project that names a base and installs nothing should not get an apt
+// invocation it never asked for.
+func TestSandboxDockerfileWithNoPackagesIsJustTheBase(t *testing.T) {
+	df, err := SandboxDockerfile("ubuntu:22.04", nil)
+	if err != nil {
+		t.Fatalf("build: %v", err)
+	}
+	if df != "FROM ubuntu:22.04\n" {
+		t.Errorf("dockerfile = %q, want only the FROM line", df)
+	}
+}
+
+// Identical content must resolve to the same tag, or every turn rebuilds an
+// image that already exists.
+func TestSandboxContentTagIsStableAndContentAddressed(t *testing.T) {
+	a, _ := SandboxDockerfile("ubuntu:22.04", []string{"gcc", "make"})
+	again, _ := SandboxDockerfile("ubuntu:22.04", []string{"gcc", "make"})
+	different, _ := SandboxDockerfile("ubuntu:22.04", []string{"gcc"})
+
+	if SandboxContentTag(a) != SandboxContentTag(again) {
+		t.Error("the same content produced two different tags")
+	}
+	if SandboxContentTag(a) == SandboxContentTag(different) {
+		t.Error("different content produced the same tag")
+	}
+	tag := SandboxContentTag(a)
+	if !strings.HasPrefix(tag, "aimee-sbx:") {
+		t.Errorf("tag = %q, want the aimee-sbx prefix", tag)
+	}
+	// The existing tag shape must be preserved or previously built images stop
+	// being found and every sandbox rebuilds.
+	if got := len(strings.TrimPrefix(tag, "aimee-sbx:")); got != 12 {
+		t.Errorf("tag hash length = %d, want 12", got)
+	}
+}
+
+// The repo's own declaration wins: a project that says it needs a Rust
+// toolchain is right about that, whatever the workspace or installation prefers.
+func TestResolveSandboxImagePrecedence(t *testing.T) {
+	all := SandboxImageCandidates{
+		Project: "proj:1", Workspace: "ws:1", Global: "glob:1",
+	}
+	ref, source, err := ResolveSandboxImage(all)
+	if err != nil || ref != "proj:1" || source != SandboxImageProject {
+		t.Errorf("ref=%q source=%v err=%v, want the project image", ref, source, err)
+	}
+
+	ref, source, _ = ResolveSandboxImage(SandboxImageCandidates{Workspace: "ws:1", Global: "glob:1"})
+	if ref != "ws:1" || source != SandboxImageWorkspace {
+		t.Errorf("ref=%q source=%v, want the workspace image", ref, source)
+	}
+
+	ref, source, _ = ResolveSandboxImage(SandboxImageCandidates{Global: "glob:1"})
+	if ref != "glob:1" || source != SandboxImageGlobal {
+		t.Errorf("ref=%q source=%v, want the global image", ref, source)
+	}
+
+	// Nothing configured is not an error: the caller runs its default image.
+	ref, source, err = ResolveSandboxImage(SandboxImageCandidates{})
+	if ref != "" || source != SandboxImageNone || err != nil {
+		t.Errorf("ref=%q source=%v err=%v, want no image and no error", ref, source, err)
+	}
+}
+
+// Falling through to a less specific image would run the delegate with a
+// toolchain nobody chose, so an invalid reference is refused instead.
+func TestResolveSandboxImageRefusesRatherThanFallingThrough(t *testing.T) {
+	_, _, err := ResolveSandboxImage(SandboxImageCandidates{
+		Project: "evil;rm -rf /", Global: "ubuntu:22.04",
+	})
+	if err == nil {
+		t.Error("an invalid project image silently fell through to the global default")
+	}
+}
diff --git a/server-go/modules/delegates/verify_test.go b/server-go/modules/delegates/verify_test.go
new file mode 100644
--- /dev/null
+++ b/server-go/modules/delegates/verify_test.go
@@ -0,0 +1,152 @@
+package delegates
+
+import (
+	"encoding/binary"
+	"testing"
+
+	"github.com/JBailes/aimee/server-go/bus"
+)
+
+// Linux's ceiling, 128+SIGRTMAX. The tests that care about the platform pass
+// their own.
+const linuxMaxSignalStatus int32 = 192
+
+// Ported from test_delegate_verify.c.
+func TestClassifyVerify(t *testing.T) {
+	cases := []struct {
+		name string
+		rc   int32
+		want VerifyOutcome
+	}{
+		{"clean run", 0, VerifyPass},
+		{"could not spawn", -1, VerifyInfraError},
+		{"ordinary test failure", 1, VerifyFailed},
+		{"not executable", 126, VerifyInfraError},
+		{"not found", 127, VerifyInfraError},
+		{"timeout expiry", 124, VerifyInfraError},
+		{"killed by SIGKILL", 137, VerifyInfraError},
+		{"killed by SIGTERM", 143, VerifyInfraError},
+		// 128 is not 128+N for any signal N, so it is an ordinary status.
+		{"exit 128", 128, VerifyFailed},
+		// Above the platform's signal ceiling a verifier may document its own
+		// meaning; suppressing escalation there is the mistake this
+		// classification exists to avoid, in the other direction.
+		{"documented high exit", 200, VerifyFailed},
+	}
+	for _, c := range cases {
+		if got := ClassifyVerify(c.rc, linuxMaxSignalStatus); got != c.want {
+			t.Errorf("%s: rc %d -> %v, want %v", c.name, c.rc, got, c.want)
+		}
+	}
+}
+
+// The ceiling is the caller's, not a constant: the same status is a signal
+// death on a platform with realtime signals and a deliberate exit without them.
+func TestClassifyVerifyRespectsThePlatformCeiling(t *testing.T) {
+	const noRealtimeSignals int32 = 159 // 128 + 31
+
+	if got := ClassifyVerify(160, linuxMaxSignalStatus); got != VerifyInfraError {
+		t.Errorf("160 under a Linux ceiling = %v, want infra_error", got)
+	}
+	if got := ClassifyVerify(160, noRealtimeSignals); got != VerifyFailed {
+		t.Errorf("160 above a low ceiling = %v, want failed", got)
+	}
+
+	// The boundary itself, stated as the rule rather than as literals: the
+	// ceiling is the last status a signal can produce, and one past it is an
+	// ordinary exit again.
+	for _, ceiling := range []int32{linuxMaxSignalStatus, noRealtimeSignals} {
+		if got := ClassifyVerify(ceiling, ceiling); got != VerifyInfraError {
+			t.Errorf("ceiling %d = %v, want infra_error", ceiling, got)
+		}
+		if got := ClassifyVerify(ceiling+1, ceiling); got != VerifyFailed {
+			t.Errorf("ceiling+1 under %d = %v, want failed", ceiling, got)
+		}
+	}
+	// 255 is above every plausible ceiling.
+	if got := ClassifyVerify(255, linuxMaxSignalStatus); got != VerifyFailed {
+		t.Errorf("255 = %v, want failed", got)
+	}
+}
+
+func TestVerifyOutcomeNames(t *testing.T) {
+	for outcome, want := range map[VerifyOutcome]string{
+		VerifyPass:       "pass",
+		VerifyFailed:     "failed",
+		VerifyInfraError: "infra_error",
+		VerifyOutcome(9): "unknown",
+	} {
+		if got := outcome.String(); got != want {
+			t.Errorf("%d = %q, want %q", outcome, got, want)
+		}
+	}
+}
+
+func TestVerifyEscalationWarranted(t *testing.T) {
+	if !VerifyEscalationWarranted(0, VerifyFailed) {
+		t.Error("a completed run with a genuine verifier failure should be reported")
+	}
+	// An unfinished delegate run is an availability problem, not a statement
+	// about the seat.
+	if VerifyEscalationWarranted(1, VerifyFailed) {
+		t.Error("a delegate run that did not complete was reported as a misplacement")
+	}
+	// Infrastructure says nothing about the work product, and no verifier at
+	// all is no signal.
+	if VerifyEscalationWarranted(0, VerifyInfraError) {
+		t.Error("an infrastructure failure was reported as a misplacement")
+	}
+	if VerifyEscalationWarranted(0, VerifyPass) {
+		t.Error("a passing verifier was reported as a misplacement")
+	}
+}
+
+func verifyRequestBytes(execRC, delegateRC, maxSignal int32) []byte {
+	request := make([]byte, verifyRequestLen)
+	binary.LittleEndian.PutUint32(request[0:4], verifyRequestMagic)
+	request[4] = wireVersion
+	binary.LittleEndian.PutUint32(request[8:12], uint32(execRC))
+	binary.LittleEndian.PutUint32(request[12:16], uint32(delegateRC))
+	binary.LittleEndian.PutUint32(request[16:20], uint32(maxSignal))
+	return request
+}
+
+func TestVerifyStageRoundTrip(t *testing.T) {
+	response, status := Handle(bus.ModuleInvocation{StageID: StageVerify},
+		verifyRequestBytes(1, 0, linuxMaxSignalStatus))
+	if status != bus.ModuleStatusOK || len(response) != verifyResponseLen ||
+		binary.LittleEndian.Uint32(response[0:4]) != verifyResponseMagic {
+		t.Fatalf("status %d, %d bytes", status, len(response))
+	}
+	if VerifyOutcome(binary.LittleEndian.Uint32(response[4:8])) != VerifyFailed {
+		t.Error("a test failure did not classify as failed")
+	}
+	if binary.LittleEndian.Uint32(response[8:12]) != 1 {
+		t.Error("escalation was not reported for a genuine failure")
+	}
+
+	// A killed verifier is infrastructure, and carries no escalation.
+	response, _ = Handle(bus.ModuleInvocation{StageID: StageVerify},
+		verifyRequestBytes(137, 0, linuxMaxSignalStatus))
+	if VerifyOutcome(binary.LittleEndian.Uint32(response[4:8])) != VerifyInfraError ||
+		binary.LittleEndian.Uint32(response[8:12]) != 0 {
+		t.Error("an OOM kill was blamed on the model")
+	}
+}
+
+func TestVerifyStageRejectsInvalidEnvelope(t *testing.T) {
+	short := verifyRequestBytes(0, 0, linuxMaxSignalStatus)[:verifyRequestLen-1]
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageVerify}, short); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("truncated status = %d", status)
+	}
+	// A ceiling below 128 cannot be a signal status; taking it would silently
+	// reclassify every killed verifier as a work-product failure.
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageVerify},
+		verifyRequestBytes(137, 0, 12)); status != bus.ModuleStatusInvalidRequest {
+		t.Errorf("nonsense ceiling status = %d", status)
+	}
+	if _, status := Handle(bus.ModuleInvocation{StageID: StageVerify, DeadlineNS: 1},
+		verifyRequestBytes(0, 0, linuxMaxSignalStatus)); status != bus.ModuleStatusCancelled {
+		t.Errorf("expired status = %d", status)
+	}
+}
