-   cJSON *args = cJSON_Parse(r.calls[0].arguments);
-   const cJSON *command = cJSON_GetObjectItemCaseSensitive(args, "command");
-   assert(cJSON_IsString(command) && strcmp(command->valuestring, "ls -la") == 0);
