-   memset(&r, 0, sizeof(r));
-   assert(delegate_rescue_parse_tool_calls("{\"name\": \"bash\", \"args\": {\"command\": \"x\"}}",
-                                           &r, 1) == 1);
-   assert(strstr(r.calls[0].arguments, "\"x\"") != NULL);
-   agent_free_parsed_response(&r);
-   printf("  tool/parameters spelling: ok\n");
