-    * rest dropped, rather than overrunning the fixed array. */
-   size_t n = (size_t)AGENT_MAX_TOOL_CALLS + 8;
-   size_t cap = n * 96 + 64;
-   char *buf = malloc(cap);
-   assert(buf);
-   buf[0] = '\0';
