-    if (self->current->local_minimum_spectrum[k] < floor_val) {
-      self->current->local_minimum_spectrum[k] = floor_val;
-    }
-    if (self->previous->local_minimum_spectrum[k] < floor_val) {
-      self->previous->local_minimum_spectrum[k] = floor_val;
